function acIdx(i){if(typeof i==='number')return i;const k=normT(String(i||''));if(!k)return -1;let j=ACOMOD.findIndex(x=>normT(x)===k);if(j<0&&/tempo/.test(k)&&/(teste|prova|ficha)/.test(k))j=9;return j}
