const KEY='edugest.v2';
/* ===== EduSpruce · os dados vivem só na base de dados: nada fica guardado neste aparelho =====
   os dados da app (estado, cópias, conflitos, ficha MRA) ficam só na memória enquanto a app está aberta; ao abrir, vêm da base de dados */
const ES_MEM={};const ES_DADOS=k=>k===KEY||k.startsWith(KEY+'.')||k==='edugest.nuvem.conf'||k.startsWith('mra.');window.__esSoNuvem=true;
window.__esLerLocal=(()=>{try{const L=JSON.parse(localStorage.getItem('edugest.nuvem')||'{}');if(!localStorage.getItem(KEY))return false;
  /* só se lê a cópia antiga deste aparelho enquanto ela ainda não passou para a base de dados (alterações por enviar, ou ainda sem nenhuma sincronização com a base de dados) */
  return !(L.prov==='supabase'&&L.sbOk&&!(L.mod&&Object.keys(L.mod).length))}catch(_){return true}})();
try{Object.keys(localStorage).forEach(k=>{if(k.startsWith('mra.')||(window.__esLerLocal&&ES_DADOS(k)))ES_MEM[k]=localStorage.getItem(k)})}catch(_){}
if(!window.__esLerLocal){try{const L=JSON.parse(localStorage.getItem('edugest.nuvem')||'{}');if(L.prov&&(L.base||Object.keys(L.mod||{}).length)){L.base=null;L.mod={};localStorage.setItem('edugest.nuvem',JSON.stringify(L))}}catch(_){}}
{const P_=Storage.prototype,gi=P_.getItem,si=P_.setItem,ri=P_.removeItem;window.__esLS={gi,si,ri};
  P_.getItem=function(k){if(this===window.localStorage&&ES_DADOS(String(k)))return Object.prototype.hasOwnProperty.call(ES_MEM,k)?ES_MEM[k]:null;return gi.call(this,k)};
  P_.setItem=function(k,v){if(this===window.localStorage&&ES_DADOS(String(k))){ES_MEM[k]=String(v);if(String(k).startsWith('mra.')){try{window.__esMraMud&&window.__esMraMud()}catch(_){}}return}return si.call(this,k,v)};
  P_.removeItem=function(k){if(this===window.localStorage&&ES_DADOS(String(k))){delete ES_MEM[k];return}return ri.call(this,k)}}
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
function anoAuto(){const d=new Date(),y=d.getFullYear(),m=d.getMonth()+1;return m>=9?y+'/'+(y+1):(y-1)+'/'+y}
function vazio(){return {cfg:{escola:'',professor:'',email:'',grupo:'',disciplinas:[],extra:[],tipos:TIPOS_INST.slice(),sinteses:Object.assign({},SINTESE_DEF)},anos:[],anoAtivo:null,turmaAtiva:null}}
function migrate(s){
  const v=vazio();s.cfg=Object.assign(v.cfg,s.cfg||{});s.anos=s.anos||[];
  // disciplinas antigas (só o nome) → uma por ciclo (os ciclos das turmas existentes, ou todos)
  s.cfg.disciplinas=[...new Set((s.cfg.disciplinas||[]).flatMap(n=>{if(String(n).includes('|'))return [n];const d=DISCIPLINAS.find(x=>x.n===n);if(!d)return [n];
    const usados=[...new Set(s.anos.flatMap(a=>(a.turmas||[]).filter(t=>t.disciplina===n).map(t=>t.ofertaDe==='profij'||t.oferta==='profij'?'profij':t.ciclo)).filter(c=>d.c.includes(c)))];
    return (usados.length?usados:d.c).map(c=>n+'|'+c)}))];
  s.anos.forEach(a=>{prepAno(a);a.org=a.org||'periodo';a.horarios=a.horarios||{};a.turmas=a.turmas||[];a.turmas.forEach(t=>{t.alunos=t.alunos||[];t.instrumentos=t.instrumentos||[];t.dominios=t.dominios||[];t.mencoes=t.mencoes||MENCOES_DEF.map(m=>({...m}));t.regra=t.regra||{2:'media',3:'media'};t.oferta=t.oferta==='profij'||t.oferta==='profissional'?t.oferta:'regular';t.alunos.forEach(x=>{if(x.frequenta===undefined)x.frequenta=true;if(x._genManual){x.generoManual=true;delete x._genManual}})})});
  return s;
}
