    <div class="kpi"><div class="l">${ic('clipboard',14)} Avaliações Marcadas</div><div class="v">${insts.length}</div><div class="mut">${c.periodos.map(p=>p.n+'.º '+insts.filter(i=>+i.periodo===p.n).length).join(' · ')}</div></div>
