  bindPainelAval(t,a);
  $$('[data-go-cal]').forEach(b=>b.onclick=e=>{e.preventDefault();UI.calTab='cal';go('calendario');setTimeout(()=>{const k=$('#ai-card');if(k)k.scrollIntoView({block:'start'})},50)});
