function tipoDeFicheiro(f){const n=(f.name||'').toLowerCase(),m=f.type||'';if(/audio/.test(m)||/\.(mp3|m4a|wav|ogg)$/.test(n))return 'audio';if(/image/.test(m))return 'imagem';if(/\.(ppt|pptx|key|odp)$/.test(n))return 'apres';if(/\.(xls|xlsx|csv|ods|numbers)$/.test(n))return 'folha';if(/teste|prova|exame/.test(n))return 'teste';return 'ficha'}
