  const fl=(id,k)=>{const el=$('#'+id);if(el)el.onchange=()=>{f[k]=el.value;vRecursos()}};fl('rf-disc','disc');fl('rf-ano','ano');fl('rf-tipo','tipo');fl('rf-col','col');fl('rf-al','al');fl('rf-ord','ord');
