  $$('[data-dv]').forEach(b=>b.onclick=()=>{const ta=$('#md-x');const p=ta.selectionStart||ta.value.length;ta.value=ta.value.slice(0,p)+'{{'+b.dataset.dv+'}}'+ta.value.slice(p)});
