  const ap=$('#da-apr');if(ap)ap.onclick=()=>{d.estado='aprovado';d.aprovadoPor=(SESSAO||{}).nome||profNome(S.cfg.professor);d.aprovadoEm=Date.now();saveNow();audit('Documentos','Documento aprovado',d.numero);abrirDocArquivo(id)};
  $('#da-env').onclick=()=>{d.estado='enviado';saveNow();audit('Documentos','Documento enviado',d.numero);abrirDocArquivo(id)};
