/* ---------- Avisos urgentes (pop-up) ---------- */
const avisosM=()=>S.avisos=S.avisos||[];
const avVistos=()=>S.cfg.avVistos=S.cfg.avVistos||{};
function avisosUrgentes(){const a=A();const agora=Date.now(),hj=isoData(new Date());const V=avVistos();const L=[];const ok=k=>!(V[k]&&V[k]>agora);
  avisosM().filter(x=>!x.feito&&x.quando&&new Date(x.quando).getTime()<=agora).forEach(x=>{const k='m:'+x.id;if(ok(k))L.push({k,ic:'alert',cor:'#c0392b',t:x.t,s:(x.txt?x.txt+' · ':'')+new Date(x.quando).toLocaleString('pt-PT',{dateStyle:'short',timeStyle:'short'}),man:x.id})});
  if(a)reunioes(a).filter(r=>reunAtiva(r)&&r.data===hj&&!r.semHora).forEach(r=>{const ms=reunInicio(r)-agora;if(ms<=60*60000&&reunFim(r)>agora){const k='r:'+r.id;if(ok(k))L.push({k,ic:'meet',cor:'#0f8b8d',t:reunTitulo(r,a),s:(ms>0?'Começa '+quandoTxt(r):'A decorrer')+(r.local?' · '+r.local:''),ir:()=>reuniaoVer(r.id)})}});
  tarefas().filter(x=>!x.feito&&x.prazo&&x.prazo<=hj&&(x.prio==='alta'||x.prazo<hj)).forEach(x=>{const k='t:'+x.id+':'+hj;if(ok(k))L.push({k,ic:'checks',cor:'#e07a00',t:x.t,s:x.prazo<hj?'Tarefa em atraso ('+contagem(x.prazo)+')':'Tarefa urgente para hoje',ir:()=>go('tarefas')})});
  if(a)try{matrizes(a).filter(x=>!x.enviada&&x.i.data>=hj&&x.data<=hj).forEach(x=>{const k='z:'+x.t.id+':'+x.i.id+':'+hj;if(ok(k))L.push({k,ic:'file',cor:'#7a4fd0',t:'Enviar a matriz: '+x.i.nome+' · '+x.t.nome,s:'Teste '+fmtIsoL(x.i.data)+(x.data<hj?' · envio em atraso':''),ir:()=>{S.turmaAtiva=x.t.id;go('testes')}})})}catch(_){}
  return L}
function mostrarAvisos(forcar){if(document.body.classList.contains('login-on')||!SESSAO)return;const L=avisosUrgentes();const ex=$('#avpop');if(!L.length){if(ex&&!forcar)ex.remove();if(forcar)toast('Não há avisos urgentes');return}
  const sig=L.map(x=>x.k).join('|');if(ex&&ex.dataset.sig===sig)return;if(ex)ex.remove();
  const o=document.createElement('div');o.id='avpop';o.dataset.sig=sig;o.setAttribute('role','alertdialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-labelledby','avpop-t');
  o.innerHTML=`<div class="avpbox"><div class="avh"><span class="avi">${ic('bell',22)}</span><div><b id="avpop-t">Avisos Urgentes</b><span>${L.length} aviso${L.length>1?'s':''} a precisar de atenção</span></div><button class="btn sm ico" id="av-x" aria-label="Fechar">${ic('x',14)}</button></div>
    <div class="avl">${L.map((x,i)=>`<div class="avit" style="--ac:${x.cor}"><span class="avic">${ic(x.ic,18)}</span><div class="avt"><b>${esc(x.t)}</b><span>${esc(x.s)}</span></div><div class="avacts">${x.ir?`<button class="btn sm pri" data-avgo="${i}">Abrir</button>`:''}<button class="btn sm" data-avad="${i}" title="Lembrar daqui a 1 hora">${ic('clock',13)} 1 h</button><button class="btn sm" data-avok="${i}">${ic('check',13)} Visto</button></div></div>`).join('')}</div>
    <div class="row avf"><button class="btn" id="av-all">${ic('check',14)} Marcar Todos Como Vistos</button><span class="sp1"></span><button class="btn pri" id="av-fe">Fechar</button></div></div>`;
  document.body.appendChild(o);try{navigator.vibrate&&navigator.vibrate([60,40,60])}catch(_){}
  const visto=(x,ms)=>{if(x.man&&!ms){const m=avisosM().find(z=>z.id===x.man);if(m)m.feito=true}avVistos()[x.k]=ms?Date.now()+ms:Date.now()+400*864e5;save();audit('Avisos',ms?'Adiado':'Visto',x.t)};
  const fecha=()=>{o.classList.add('sai');setTimeout(()=>o.remove(),200)};const prox=()=>{const r=avisosUrgentes();if(!r.length)fecha();else{o.remove();mostrarAvisos()}};
  $$('[data-avgo]',o).forEach(b=>b.onclick=()=>{const x=L[+b.dataset.avgo];fecha();x.ir()});$$('[data-avok]',o).forEach(b=>b.onclick=()=>{visto(L[+b.dataset.avok]);prox()});$$('[data-avad]',o).forEach(b=>b.onclick=()=>{visto(L[+b.dataset.avad],3600000);prox()});
  $('#av-all').onclick=()=>{L.forEach(x=>visto(x));fecha()};$('#av-fe').onclick=()=>{L.forEach(x=>{if(!avVistos()[x.k])avVistos()[x.k]=Date.now()+30*60000});save();fecha()};$('#av-x').onclick=$('#av-fe').onclick;setTimeout(()=>{const b=$('#av-fe');if(b)b.focus()},50)}
setInterval(()=>{try{mostrarAvisos()}catch(_){}},60000);
