/* ZIP mínimo (sem compressão) */
const CRCT=(()=>{const T_=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;T_[n]=c>>>0}return T_})();
