function sintDados(t,a,per){const pf=pctsFinal(t,a.id,per);const f=ponderada(t,pf);const doms=t.dominios.filter(d=>pf[d.id]!=null).map(d=>({d,v:pf[d.id]})).sort((x,y)=>y.v-x.v);
  let prev=null;if(per>1){const n1=ponderada(t,pctsPer(t,a.id,per-1)),n2=ponderada(t,pctsPer(t,a.id,per));if(n1!=null&&n2!=null)prev=n2-n1}
  const I=t.instrumentos.filter(i=>+i.periodo===+per&&instMax(i)&&instAvaliado(i,a.id)).sort((x,y)=>(x.data||'').localeCompare(y.data||''));const tr=I.length>=2?instTotal(I[I.length-1],a.id)/instMax(I[I.length-1])-instTotal(I[0],a.id)/instMax(I[0]):null;
  let L=[];try{L=listaAulas(t,A()).filter(x=>x.licao&&x.per===+per&&aulaConf(x))}catch(_){}let F=0,J=0,FD=0,FM=0,AT=0,pos=0,neg=0;const notas=[];
  L.forEach(x=>{const p=(x.s&&x.s.pres||{})[a.id];if(!p)return;if(p.f==='FD')FD++;else if(p.f){F++;if(p.j||p.just)J++}if(p.fm)FM++;if(p.at)AT++;if(p.oc&&p.oc.n){if(p.oc.n==='positiva')pos++;else neg++}if(p.oc&&p.oc.t)notas.push(p.oc.t)});
  let inter=null;try{const M=intMomentos(t,A()).find(m=>m.p===+per);inter=M&&(t.interc||{})[M.id]&&t.interc[M.id][a.id]}catch(_){}
  const med=a.medidas||{};const nMed=['univ','selet','adic'].reduce((s_,k)=>s_+((med[k]||[]).length),0);
  return {pf,f,doms,prev,tr,aulas:L.length,F,J,FD,FM,AT,pos,neg,notas,inter,nMed,nInst:I.length}}

/* ===================== v0.52 · Síntese descritiva: português padrão e linguagem pedagógica ===================== */
const _g=(a,m)=>a.genero==='F'?m.replace(/o$/,'a').replace(/os$/,'as'):m;
function artDom(nome){const raw=String(nome||'').trim();const txt=raw.split(/\s+/).map(p=>p.length>1&&p===p.toUpperCase()?p:p.toLowerCase()).join(' ');const w=normT(raw.split(/\s+/)[0]||'');
  const art=/(coes|oes|ades|agens|as|des)$/.test(w)?'as':/(os|es)$/.test(w)?'os':/(a|cao|ao|ade|agem|ice|ude)$/.test(w)?'a':'o';return [art,txt]}
function emDom(nome){const [a,t]=artDom(nome);return ({a:'na',o:'no',as:'nas',os:'nos'})[a]+' '+t}
function oDom(nome){const [a,t]=artDom(nome);return a+' '+t}
const SINT_REC2=[[/compreensao oral|ouvir|audi/,'ouça regularmente textos e registos áudio'],[/oral|falar|expressao oral|producao oral/,'participe oralmente com mais frequência'],[/leitura|compreensao escrita|ler|liter/,'leia com mais regularidade'],[/escrita|producao escrita|reda/,'pratique com regularidade a escrita de textos e reveja a sua correção'],[/gramatica|conhecimento expl|lingua/,'reveja e aplique as regras gramaticais'],[/calculo|numero|algebra|geometria/,'resolva exercícios com regularidade'],[/problema/,'treine a resolução de problemas'],[/experimental|pratic|laborat|fisica/,'se empenhe mais nas atividades práticas'],[/atitude|valor|comport|responsab|social/,'cumpra as regras combinadas e participe de forma responsável'],[/conhecimento|capacidade|conteudo/,'consolide os conteúdos através de um estudo regular']];
/* (substituída na v0.53) */
/* ===================== v0.53 · Síntese descritiva minuciosa, sem repetições entre períodos ===================== */
const _vs=(a,per,k,L)=>L[(Math.abs(_hs((a.id||a.nome)+'|'+k))+(+per||1))%L.length];
const SINT_PLANO=[[/compreensao oral|ouvir|audi/,['ouvir, duas a três vezes por semana, registos áudio ou vídeos curtos, resumindo por palavras suas o que compreendeu','ver e ouvir conteúdos breves na língua estudada, registando as ideias principais','treinar a compreensão com os áudios do manual, primeiro sem e depois com o texto escrito']],
 [/oral|falar|expressao oral|producao oral/,['fazer, pelo menos, uma intervenção oral por aula','preparar em casa pequenas apresentações orais de dois a três minutos','ler em voz alta e gravar-se, ouvindo depois para corrigir a pronúncia e a fluência']],
 [/liter/,['ler as obras propostas com regularidade, registando num caderno as personagens, os temas e as passagens marcantes','fazer um pequeno resumo de cada capítulo lido','comparar, por escrito, as obras estudadas com outras leituras do seu gosto']],
 [/leitura|compreensao escrita|ler/,['ler diariamente, durante 15 a 20 minutos, sublinhando as ideias principais','ler textos variados (notícias, contos, textos informativos) e responder a questões de compreensão','elaborar um glossário com as palavras novas encontradas nas leituras']],
 [/escrita|producao escrita|reda/,['escrever um texto curto por semana e reescrevê-lo a partir das correções do professor','planificar os textos antes de escrever (ideias, organização, conclusão)','rever sempre os textos, verificando a ortografia, a pontuação e a coerência']],
 [/gramatica|conhecimento expl|lingua/,['resolver fichas de gramática duas vezes por semana','elaborar um resumo das regras gramaticais com exemplos próprios','rever os erros gramaticais mais frequentes nos testes e nos textos']],
 [/calculo|numero|algebra|geometria/,['resolver diariamente alguns exercícios, verificando os resultados','refazer os exercícios das aulas sem consultar a resolução','construir uma ficha-resumo com fórmulas e exemplos']],
 [/problema/,['resolver um problema por dia, explicando por escrito o raciocínio','identificar os dados e o pedido antes de resolver cada problema','discutir com colegas diferentes estratégias de resolução']],
 [/experimental|pratic|laborat|fisica/,['preparar previamente as atividades práticas','registar os procedimentos e as conclusões de cada atividade','rever a segurança e os passos de cada atividade antes da aula']],
 [/atitude|valor|comport|responsab|social/,['trazer sempre o material e cumprir os prazos','registar os trabalhos de casa na agenda e verificá-los diariamente','colaborar nas tarefas de grupo, respeitando as regras combinadas']],
 [/conhecimento|capacidade|conteudo/,['organizar um horário de estudo semanal, com revisão regular das matérias','fazer resumos e esquemas de cada unidade','testar-se com perguntas sobre a matéria antes dos testes']]];
const NIV_TXT=['dificuldades','um desempenho satisfatório','um bom desempenho','um desempenho muito bom'];
const nivTxt=v=>v>=.895?3:v>=.695?2:v>=.495?1:0;
const juntaE=L=>L.length<2?(L[0]||''):L.slice(0,-1).join(', ')+' e '+L[L.length-1];
function sintesePers(t,a,per,cfg){cfg=cfg||SINT_CFG();const D=sintDados(t,a,per);const w=perW().toLowerCase();const nm=a.nome.split(' ')[0];const F=a.genero==='F';const Su=(F?'a ':'o ')+nm;const SU=(F?'A ':'O ')+nm;const ext=cfg.ext||'completa';const P=[];const dsc=t.disciplina;
  const nP=periodos().length;const ult=+per===nP;const sec=isSec(t);const V=(k,L)=>_vs(a,per,k,L);
  if(D.f==null)return `${SU} ainda não dispõe de elementos de avaliação suficientes no ${per}.º ${w} que permitam uma apreciação do seu desempenho.`;
  const v=D.f;const lv=v>=.895?4:v>=.695?3:v>=.495?2:1;
  /* 1. apreciação global (abertura diferente em cada período) */
  const glob=[null,V('g',[`dificuldades em ${dsc}, não tendo ainda consolidado as aprendizagens essenciais`,`um desempenho ainda insuficiente em ${dsc}, com aprendizagens essenciais por adquirir`,`dificuldades significativas em ${dsc}, que importa superar`]),
    V('g',[`um desempenho satisfatório em ${dsc}, tendo adquirido as aprendizagens essenciais, embora com algumas fragilidades`,`um desempenho suficiente em ${dsc}, com as aprendizagens essenciais adquiridas mas ainda por consolidar`,`um desempenho globalmente satisfatório em ${dsc}, com aspetos que pode ainda melhorar`]),
    V('g',[`um bom desempenho em ${dsc}, mobilizando as aprendizagens com segurança`,`um bom domínio das aprendizagens de ${dsc}, trabalhando com empenho e autonomia`,`bons resultados em ${dsc}, revelando segurança na maioria das tarefas`]),
    V('g',[`um desempenho muito bom em ${dsc}, aplicando as aprendizagens com rigor e autonomia`,`um excelente domínio das aprendizagens de ${dsc}, com resultados consistentes`,`um desempenho de grande qualidade em ${dsc}, com rigor e espírito crítico`])][lv];
  const ab=+per===1?V('ab',[`Ao longo do 1.º ${w}, ${Su} revelou `,`No 1.º ${w}, ${Su} demonstrou `,`Neste primeiro ${w}, ${Su} evidenciou `]):ult?V('ab',[`No ${per}.º ${w}, ${Su} revelou `,`Neste último ${w}, ${Su} demonstrou `,`Ao longo do ${per}.º ${w}, ${Su} evidenciou `]):V('ab',[`No ${per}.º ${w}, ${Su} revelou `,`Ao longo do ${per}.º ${w}, ${Su} demonstrou `,`Neste ${per}.º ${w}, ${Su} evidenciou `]);
  const cls=cfg.num?` (${sec?fmtNota(t,v)+' valores':'nível '+nivel(t,v)})`:'';
  P.push((ab+glob+cls+'.').replace(/^(.)/,c=>c.toUpperCase()));
  /* 2. retrato por domínio */
  const doms=D.doms;if(doms.length>1){const G=[[],[],[],[]];doms.forEach(x=>G[nivTxt(x.v)].push(emDom(x.d.nome)));const partes=[];[3,2,1,0].forEach(k=>{if(G[k].length)partes.push(NIV_TXT[k]+' '+juntaE(G[k]))});
    const uni=G.filter(g=>g.length).length===1;const ng=nivTxt(doms[0].v);
    if(uni)P.push(ng===0?V('dm',['As dificuldades manifestaram-se em todos os domínios.','As dificuldades foram transversais a todos os domínios.','Nenhum dos domínios atingiu ainda o nível desejável.']):V('dm',[`Revelou ${NIV_TXT[ng]} em todos os domínios.`,`O desempenho foi homogéneo, com ${NIV_TXT[ng]} nos diferentes domínios.`,`Manteve ${NIV_TXT[ng]} de forma equilibrada nos vários domínios.`]));
    else P.push(V('dm',['Nos diferentes domínios, revelou ','Analisando os domínios, evidenciou ','Por domínios, demonstrou '])+juntaE(partes)+'.');
    const top=doms[0],low=doms[doms.length-1];if(!uni&&top.v-low.v>=.12&&ext!=='curta')P.push(V('fr',[`O seu ponto mais forte foi ${oDom(top.d.nome)}, enquanto ${oDom(low.d.nome)} exige maior investimento.`,`Destacou-se ${emDom(top.d.nome)}, sendo ${oDom(low.d.nome)} o domínio que mais precisa de atenção.`,`Os melhores resultados surgiram ${emDom(top.d.nome)}; já ${oDom(low.d.nome)} requer um trabalho mais sistemático.`]))}
  /* 3. evolução face ao período anterior (por domínio) */
  if(+per>1&&cfg.evol!==false&&ext!=='curta'){const pa=pctsPer(t,a.id,per-1),pc=pctsPer(t,a.id,per);const up=[],dn=[];t.dominios.forEach(d=>{if(pa[d.id]==null||pc[d.id]==null)return;const dd=pc[d.id]-pa[d.id];if(dd>=.05)up.push(emDom(d.nome));else if(dd<=-.05)dn.push(emDom(d.nome))});
    const g0=ponderada(t,pa),g1=ponderada(t,pc);const ant=`${per-1}.º ${w}`;
    if(g0!=null&&g1!=null){const dg=g1-g0;let fr=Math.abs(dg)<.03?V('ev',[`Comparativamente ao ${ant}, manteve o nível de desempenho`,`Face ao ${ant}, o desempenho manteve-se estável`]):dg>0?V('ev',[`Comparativamente ao ${ant}, registou uma evolução positiva, que se valoriza`,`Face ao ${ant}, progrediu de forma visível`,`Em relação ao ${ant}, melhorou os seus resultados`]):V('ev',[`Comparativamente ao ${ant}, registou um decréscimo nos resultados`,`Face ao ${ant}, os resultados desceram`]);
      const nD=t.dominios.filter(d=>pa[d.id]!=null&&pc[d.id]!=null).length;if(up.length)fr+=up.length===nD&&nD>2?', com progressos em todos os domínios':`, com progressos ${juntaE(up)}`;if(dn.length)fr+=(up.length?', mas ':', ')+(dn.length===nD&&nD>2?'com descida em todos os domínios':`com descida ${juntaE(dn)}`);P.push(fr+'.');if(dg<=-.03)P.push(V('dsc',['É importante recuperar o ritmo de trabalho e identificar, com o professor, as causas desta descida.','Importa perceber as razões desta descida e reforçar o estudo regular.','Esta descida exige atenção e um maior investimento no trabalho diário.']))}}
  else if(D.tr!=null&&Math.abs(D.tr)>=.08&&ext!=='curta')P.push(D.tr>0?V('tr',['Foi melhorando os seus resultados ao longo do período, o que se valoriza.','Os resultados foram subindo de instrumento para instrumento, sinal de um trabalho mais consistente.']):'Os resultados foram descendo ao longo do período, pelo que é importante recuperar o ritmo de trabalho.');
  /* 4. atitudes, assiduidade e participação */
  if(ext!=='curta'){let difA=false;if(cfg.assid!==false&&D.aulas){const fi=D.F-D.J;if(fi>=3||D.FD){P.push(V('as',['As faltas registadas condicionaram o seu percurso, pelo que é essencial uma frequência regular.','A assiduidade foi irregular, o que prejudicou a continuidade das aprendizagens.']));difA=true}else if(!D.F&&D.AT<2)P.push(V('as',[_g(a,'Foi assíduo')+' e pontual.',_g(a,'Foi assíduo')+' e pontual ao longo do período.','Revelou assiduidade e pontualidade.']));else P.push(V('as2',[_g(a,'Foi assíduo'),'Revelou uma assiduidade regular',_g(a,'Esteve presente')+' com regularidade'])+(D.AT>=2?V('at',[', embora tenha chegado '+_g(a,'atrasado')+' algumas vezes',', mas deve melhorar a pontualidade',', embora com alguns atrasos']):'')+'.');if(D.FM>=2)P.push('Deve trazer sempre o material necessário para as aulas.')}
    if(cfg.comp!==false){if(D.neg>=2&&D.neg>D.pos)P.push('Precisa de melhorar a atenção e o cumprimento das regras da sala de aula.');else if(D.pos>=2||lv>=3)P.push((difA?'Participou, no entanto, ':'Participou ')+V('pt',['com interesse e empenho nas atividades propostas.','de forma ativa e interessada nas atividades da aula.','com empenho, colaborando com os colegas.']));else if(lv<=2)P.push(V('pt',['Deve participar mais nas atividades da aula, colocando as suas dúvidas.','Uma participação mais ativa nas aulas ajudá-'+(F?'la':'lo')+'-á a progredir.','Deve envolver-se mais nas tarefas da aula e pedir ajuda sempre que precisar.']))}
    if(ext==='completa'&&D.inter&&D.inter.obs&&+per!==nP)P.push(D.inter.obs.trim().replace(/([^.!?])$/,'$1.'))}
  /* 5. balanço do ano (último período) */
  if(ult&&nP>1&&ext!=='curta'){const traj=[];for(let p=1;p<=nP;p++){const g=ponderada(t,pctsPer(t,a.id,p));if(g!=null)traj.push({p,g})}
    if(traj.length>=2){const i0=traj[0],i1=traj[traj.length-1];const d0=NIV_TXT[nivTxt(i0.g)],d1=NIV_TXT[nivTxt(i1.g)];const sub=i1.g-i0.g;
      const fx=d0===d1?(sub>=.05?`manteve ${d0}, mas com progressos visíveis ao longo do ano, o que demonstra esforço`:sub<=-.05?`manteve ${d0}, embora com uma descida dos resultados ao longo do ano, pelo que deverá retomar os hábitos de trabalho do início do ano`:`manteve ${d0} ao longo de todo o ano`):sub>=.05?`passou de ${d0} no ${i0.p}.º ${w} para ${d1} no ${i1.p}.º ${w}, o que demonstra esforço e capacidade de superação`:`passou de ${d0} no ${i0.p}.º ${w} para ${d1} no ${i1.p}.º ${w}, pelo que deverá retomar os hábitos de trabalho do início do ano`;
      P.push(`Em balanço do ano letivo, ${Su} ${fx}.`)}}
  /* 6. recomendações (curta) ou plano de estudo e trabalho */
  if(cfg.recom!==false){const fr=doms.filter(x=>x.v<(lv>=3?.7:.6)).slice(-2).reverse();const nrm=x=>normT(x.d.nome);
    if(ext==='curta'){const recs=[...new Set(fr.map(x=>{const m=SINT_REC2.find(([re])=>re.test(nrm(x)));return m?m[1]:'consolide '+x.d.nome.toLowerCase()+' com trabalho regular'}))];const lst=L=>L.length>1?L.slice(0,-1).join(', ')+' e que '+L[L.length-1]:L[0];
      P.push(lv<=2?`Para progredir, recomenda-se que ${recs.length?lst(recs):'mantenha um estudo regular e esclareça as dúvidas nas aulas'}.`:lv===3&&recs.length?`Para melhorar, recomenda-se que ${lst(recs)}.`:'Deve manter o empenho demonstrado.')}
    else{const it=[];fr.forEach(x=>{const m=SINT_PLANO.find(([re])=>re.test(nrm(x)));if(m){const o=V('pd'+nrm(x),m[1]);if(!it.includes(o))it.push(o)}});
      if(lv<=2){it.push(V('pl',['analisar os testes corrigidos e refazer os exercícios em que errou','rever, no final de cada semana, os conteúdos trabalhados nas aulas','fazer um resumo da matéria de cada aula no próprio dia']));it.push(V('pl2',['esclarecer as dúvidas no final de cada aula, sem as deixar acumular','preparar cada teste com, pelo menos, uma semana de antecedência, usando fichas de revisão','estudar todos os dias à mesma hora, num local tranquilo e sem distrações']))}
      else if(lv===3)it.push(V('pl',['rever regularmente os conteúdos e resolver exercícios de maior complexidade','preparar os testes com antecedência e analisar os erros cometidos','alargar as leituras e as pesquisas sobre os temas estudados']));
      else it.push(V('pl',['aprofundar os conteúdos com leituras e desafios adicionais','explorar temas do seu interesse ligados à disciplina e partilhá-los com a turma','apoiar os colegas, consolidando as suas próprias aprendizagens']));
      if(lv===1)it.push(D.nMed?'tirar partido das medidas de apoio definidas':'frequentar os apoios disponíveis na escola');
      const prox=ult?'no próximo ano letivo':`no ${+per+1}.º ${w}`;const intro=lv===1?`Para superar as dificuldades ${prox}, propõe-se o seguinte plano de estudo e trabalho`:lv===2?`Para progredir ${prox}, propõe-se o seguinte plano de estudo e trabalho`:lv===3?`Para alcançar resultados ainda melhores ${prox}, sugere-se`:`Para continuar a evoluir ${prox}, sugere-se`;
      P.push(`${intro}: ${it.slice(0,ext==='completa'?5:3).join('; ')}.`);
      if(lv===1)P.push(V('ee',['O acompanhamento do encarregado de educação, verificando o cumprimento deste plano, será uma ajuda importante.','A colaboração do encarregado de educação no acompanhamento deste plano será determinante.','O apoio da família, acompanhando o estudo diário, fará a diferença.']))}}
  if(ext!=='curta')P.push(lv<=2?V('fim',['Com empenho e trabalho regular, conseguirá progredir.','Acreditamos que, com persistência, conseguirá melhorar os seus resultados.','Está ao seu alcance melhorar, se mantiver um trabalho regular.']):lv===3?V('fim',['Deve manter o empenho demonstrado.','Está no bom caminho e deve manter este ritmo de trabalho.','O trabalho desenvolvido merece ser valorizado.']):V('fim',['O seu percurso merece ser valorizado.','Parabéns pelo trabalho desenvolvido.','Deve manter a dedicação e o rigor demonstrados.']));
  return ext==='curta'?P.slice(0,3).join(' '):P.join(' ')}
{const _sOld=sintese;sintese=function(t,a,per){try{const c=SINT_CFG();if(c.modo==='modelos')return _sOld.apply(this,arguments);return sintesePers(t,a,per,c)}catch(e){console.warn(e);return _sOld.apply(this,arguments)}}}
function sinteseDlg(){const t=T();if(!t)return;const al=alunosFiltro(t);const per=UI.relPer||perAtual(t);const c=SINT_CFG();let k=Math.max(0,al.findIndex(x=>x.id===UI.relAluno));
  const draw=()=>{const a=al[k];const man=a&&a.sintese&&a.sintese[per];openDrawer('Síntese Descritiva Automática',`<div class="ed sintd">
    <p class="hint" style="margin-top:0">Redigida em linguagem pedagógica a partir dos resultados por domínio, da evolução, da assiduidade, das atitudes registadas nas aulas, da intercalar e das medidas de apoio: valoriza o que está conseguido, identifica o que melhorar e propõe estratégias concretas. Fica editável na folha do relatório.</p>
    <div class="g2"><div><label>Modo</label><div class="seg">${[['pers','Personalizada'],['modelos','Modelos por menção']].map(([v,l])=>`<button type="button" data-sm="${v}" class="${c.modo===v?'on':''}">${l}</button>`).join('')}</div></div>
      <div><label>Extensão</label><div class="seg">${[['curta','Curta'],['media','Média'],['completa','Completa']].map(([v,l])=>`<button type="button" data-se="${v}" class="${c.ext===v?'on':''}">${l}</button>`).join('')}</div></div></div>
    <div class="row" style="gap:14px;flex-wrap:wrap;margin:10px 0">${[['evol','Evolução'],['assid','Assiduidade'],['comp','Atitudes e participação'],['recom','Estratégias e recomendações'],['num','Indicar a classificação']].map(([v,l])=>`<label class="chk"><input type="checkbox" data-so="${v}" ${(v==='num'?!!c[v]:c[v]!==false)?'checked':''}> ${l}</label>`).join('')}</div>
    ${a?`<div class="sintpv"><div class="row" style="gap:8px"><button type="button" class="btn sm ico" data-sk="-1" ${k?'':'disabled'} aria-label="Anterior">‹</button><b>${esc(numAl(a))}. ${esc(a.nome)}</b><button type="button" class="btn sm ico" data-sk="1" ${k<al.length-1?'':'disabled'} aria-label="Seguinte">›</button><span class="sp1"></span>${man?'<span class="tag w">tem texto editado à mão</span>':''}</div><p id="sint-tx">${esc(sintese(t,a,per))}</p></div>`:'<p class="mut">Sem alunos.</p>'}
    <div class="row" style="gap:8px;margin-top:12px;flex-wrap:wrap"><span class="sp1"></span>${a&&man?`<button class="btn" id="sint-um">Substituir o texto deste aluno</button>`:''}<button class="btn" id="sint-rep">Repor nos editados à mão</button><button class="btn pri" id="sint-ok">${ic('check',14)} Aplicar</button></div></div>`);
    $$('#dw-b [data-sm]').forEach(b=>b.onclick=()=>{c.modo=b.dataset.sm;save();draw()});$$('#dw-b [data-se]').forEach(b=>b.onclick=()=>{c.ext=b.dataset.se;save();draw()});
    $$('#dw-b [data-so]').forEach(x=>x.onchange=()=>{c[x.dataset.so]=x.checked;save();draw()});$$('#dw-b [data-sk]').forEach(b=>b.onclick=()=>{k+=+b.dataset.sk;draw()});
    const um=$('#sint-um');if(um)um.onclick=()=>{delete a.sintese[per];save();toast('Síntese de '+a.nome.split(' ')[0]+' atualizada','ok');draw()};
    $('#sint-rep').onclick=()=>{const n=al.filter(x=>x.sintese&&x.sintese[per]).length;if(!n)return toast('Nenhuma síntese foi editada à mão','aviso');if(!confirm('Substituir as '+n+' sínteses editadas à mão pelo texto automático?'))return;al.forEach(x=>{if(x.sintese)delete x.sintese[per]});save();toast(n+' sínteses atualizadas','ok');draw()};
    $('#sint-ok').onclick=()=>{closeDrawer();vRelatorios();toast('Sínteses automáticas aplicadas aos relatórios','ok')}};draw()}
{const _vRS=vRelatorios;vRelatorios=function(){const r=_vRS.apply(this,arguments);try{const bx=$('#barx');if(bx&&!$('#b-sint')){bx.insertAdjacentHTML('beforeend',`<button class="btn" id="b-sint">${ic('sparkle',15)} Síntese Automática…</button>`);$('#b-sint').onclick=sinteseDlg}}catch(e){console.warn(e)}return r};if(go._f)go._f.relatorios=vRelatorios}

