{const _hDT=historicoDT;historicoDT=function(a,n,AL){const H=_hDT.apply(this,arguments)||[];try{ligarClasse(a);const vis=new Set();(AL||[]).forEach(o=>{const x=o.x||o;if(!x||!x.cid||vis.has(x.cid))return;vis.add(x.cid);contactosEE(a,x.cid).forEach(c=>H.push({data:c.data,tipo:'Contacto com o EE ('+c.meio+')',desc:x.nome.split(' ')[0]+' · '+(c.assunto||c.sintese||'')}))});H.sort((p,q)=>(q.data||'').localeCompare(p.data||''))}catch(e){console.warn(e)}return H}}
