  $('#jo-ok').onclick=()=>{cfg.nome=$('#jo-n').value.trim()||'Jornal Escolar';cfg.dias=Math.max(1,Math.min(60,+$('#jo-d').value||7));cfg.diasMat=Math.max(0,+$('#jo-m').value||0);cfg.diasEntrega=Math.max(0,+$('#jo-e').value||0);save();closeDrawer();vJornal()};
