  const e2={id:uid(),num:'2',titulo:'Edição de Natal',fecho:isoData(dia(12)),pub:isoData(dia(18)),estado:'planeada',check:[0],notas:'Capa: Concerto de Natal.',demo:true};y.edicoes.push(e1,e2);
