const turmaVisivel=t=>!acessoRestrito()||turmaMinha(t);
function turmaEditavel(t){if(!SESSAO||!t)return true;let p;try{p=perfilAtual()}catch(_){return true}return p.id==='admin'||!!(p.perm&&p.perm.editarTodas)||turmaMinha(t)}
