  const sw=sh.offsetWidth||794,shh=sh.offsetHeight||1123;const disp=w.parentElement.clientWidth-24,alt=innerHeight-(w.getBoundingClientRect().top>0?Math.min(w.getBoundingClientRect().top,200):160)-40;
