  const tl=v=>String(v).replace(/[^\d+]/g,'');const act=(i,l,h)=>h?`<a class="cmact" href="${esc(h)}"><span>${ic(i,17)}</span>${l}</a>`:`<span class="cmact off" aria-disabled="true"><span>${ic(i,17)}</span>${l}</span>`;
