  if(it.t==='audio'){const src=FOTOS[it.fid];return `<div ${A}><div class="mq-ah2"><span class="mq-aic">${ic('mic',18)}</span><input class="mq-nm" data-tit value="${esc(it.tit||'')}" placeholder="Áudio" aria-label="Nome do áudio"></div>${src?`<audio controls preload="metadata" src="${esc(src)}"></audio>`:'<div class="mq-semimg"><small>áudio ainda não disponível neste aparelho</small></div>'}${rz}</div>`}
  if(it.t==='video'){const em=mqEmbed(it.url);const src=it.fid&&FOTOS[it.fid];return `<div ${A}><div class="mq-vh">${ic('video',15)}<input class="mq-nm" data-tit value="${esc(it.tit||'')}" placeholder="Vídeo" aria-label="Nome do vídeo">${it.url?`<a class="btn sm ghost" href="${esc(it.url)}" target="_blank" rel="noopener" title="Abrir">${ic('link',13)}</a>`:''}</div><div class="mq-vid">${em?`<iframe class="mq-ifr" src="${esc(em)}" title="${esc(it.tit||'Vídeo')}" allow="encrypted-media; picture-in-picture; fullscreen" loading="lazy"></iframe>`:src?`<video controls preload="metadata" src="${esc(src)}"></video>`:it.url?`<video controls preload="metadata" src="${esc(it.url)}"></video>`:'<div class="mq-semimg"><small>vídeo indisponível</small></div>'}</div>${rz}</div>`}
  if(it.t==='mapa')return `<div ${A}><div class="mq-vh">${ic('map',15)}<input class="mq-nm" data-tit value="${esc(it.tit||it.lq||'')}" placeholder="Mapa" aria-label="Nome do mapa"><a class="btn sm ghost" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(it.lq||'')}" target="_blank" rel="noopener" title="Abrir no mapa">${ic('link',13)}</a></div><div class="mq-vid mq-map"><iframe class="mq-ifr" src="https://maps.google.com/maps?q=${encodeURIComponent(it.lq||'')}&z=${it.z||15}&output=embed" title="Mapa: ${esc(it.lq||'')}" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe></div>${rz}</div>`;
  if(it.t==='documento'){const tx=mqTxt(it.html);return `<div ${A}><div class="mq-doc"><span class="mq-doci">${ic('file',22)}</span><div><b>${esc(it.tit||'Documento sem título')}</b><small>${tx?tx.split(/\s+/).length+' palavras':'vazio'}</small></div></div>${tx?`<p class="mq-docp">${esc(tx.slice(0,180))}${tx.length>180?'…':''}</p>`:''}<button type="button" class="btn sm" data-abrir>${ic('pencil',13)} Abrir documento</button>${rz}</div>`}
  if(it.t==='esboco'){const src=it.fid&&FOTOS[it.fid];return `<div ${A}><div class="mq-esb">${src?`<img src="${esc(src)}" alt="${esc(it.tit||'Esboço')}" draggable="false">`:`<div class="mq-esbv">${ic('scribble',28)}<small>Toque duas vezes para desenhar</small></div>`}</div><input class="mq-leg" data-tit value="${esc(it.tit||'')}" placeholder="Esboço…" aria-label="Nome do esboço">${rz}</div>`}
