const ptHist=()=>{const c=S.cprofij=S.cprofij||{};return c.hist=c.hist||{}};
const ptFp=(cl,al)=>{const {y}=CP();const k=cl.nome+'|'+al.k;return y.fpct[k]=y.fpct[k]||{}};
