/* ===== 1.084: privacidade e conta — eliminar a conta (direito ao apagamento, RGPD art.º 17.º), versão dos scripts da base de dados
   e espaço ocupado por conta (administrador). As funções vêm do script 0019_seguranca_rgpd.sql; sem ele, a app explica o que falta. ===== */
const SB_BD_MIN=19;
async function sbRpc(fn,args){const p=await sbObter();const c=p.cliente;if(!c||!c.rpc)throw new Error('A base de dados não está disponível.');const {data,error}=await c.rpc(fn,args||{});
  if(error){const falta=/PGRST202|42883|Could not find the function|does not exist/i.test((error.code||'')+' '+(error.message||''));
    const e=new Error(falta?'A base de dados ainda não tem esta função: o administrador tem de correr o ficheiro 0019_seguranca_rgpd.sql no Supabase.':(error.message||'Erro na base de dados.'));e.falta=falta;throw e}return data}
let _sbBdV;async function sbBdVersao(){if(_sbBdV!==undefined)return _sbBdV;try{const v=await sbRpc('eduspruce_bd_versao');_sbBdV=typeof v==='number'?v:0}catch(e){if(e.falta)_sbBdV=0;else return null}return _sbBdV}
async function sbEliminarConta(){const em=sbEmailApp()||nvL().kDe||'esta conta';
  const r=await avisoModal('Eliminar a conta e todos os dados?',['A conta '+em+' e tudo o que lhe pertence são apagados da base de dados de uma vez, sem cópia: turmas, alunos, avaliações, sumários, testes digitalizados, formulários, provas, salas e resultados.','Não é possível desfazer. Para guardar os dados, cancele e use primeiro «Descarregar Cópia Completa».','A autorização para este e-mail entrar na EduSpruce é gerida pelo administrador e não muda.'],[{t:'Cancelar',v:null,c:'pri'},{t:'Continuar',c:'dng',v:'sim'}]);if(r!=='sim')return;
  const t=prompt('Para confirmar, escreva APAGAR (em maiúsculas).');if(t==null)return;if(t.trim()!=='APAGAR')return toast('Não escreveu APAGAR: nada foi eliminado.','aviso');
  try{await sbRpc('eduspruce_apagar_conta',{p_confirmar:'APAGAR'})}catch(e){return toast(e.message,'erro')}
  /* a conta já não existe: este aparelho esquece tudo e volta ao ecrã de entrada */
  window.__esSair=true;try{const p=await sbObter();await Promise.race([p.sair(),new Promise(ok=>setTimeout(ok,2500))])}catch(_){}
  try{sbEsquecer()}catch(_){}try{localStorage.clear();sessionStorage.clear()}catch(_){}
  try{sessionStorage.setItem('es.lgmsg','A conta e todos os dados foram eliminados.')}catch(_){}location.replace(location.origin+location.pathname)}
async function sbUsoDlg(){openDrawer('Espaço na base de dados',`<div class="ed"><p class="mut">A carregar…</p></div>`);let u;try{u=await sbRpc('eduspruce_admin_uso')}catch(e){const el=$('#dw-b .ed');if(el)el.innerHTML=`<div class="alert">${esc(e.message)}</div>`;return}
  const mb=b=>nf((+b||0)/1048576,1)+' MB';const L=u&&Array.isArray(u.por_conta)?u.por_conta:[];const el=$('#dw-b .ed');if(!el)return;
  el.innerHTML=`<p class="hint" style="margin-top:0">Base de dados inteira: <b>${mb(u.bd_bytes)}</b> · ${+u.contas||0} conta(s). O plano gratuito do Supabase tem 500 MB; as fotografias e os testes digitalizados são o que mais ocupa.</p>
    <div style="overflow:auto"><table class="lst"><thead><tr><th>Conta</th><th>Partes</th><th>Espaço</th><th>Última alteração</th></tr></thead><tbody>${L.map(x=>`<tr><td>${esc(x.email||'—')}</td><td>${+x.partes||0}</td><td>${mb(x.bytes)}</td><td>${x.ultima?esc(new Date(x.ultima).toLocaleDateString('pt-PT')):'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="mut">Sem dados.</td></tr>'}</tbody></table></div>`}
{const _bR=bindNvPainel;bindNvPainel=function(){const r=_bR.apply(this,arguments);try{const c=$('#nv-card');if(c&&nvL().prov==='supabase'){let s=c.querySelector('#nv-rgpd');
    if(!s){s=document.createElement('section');s.className='nvs';s.id='nv-rgpd';const seg=c.querySelector('#nv-seg');if(seg&&seg.parentNode)seg.parentNode.insertBefore(s,seg.nextSibling);else (c.querySelector('.card:not(.nvhero)')||c).appendChild(s)}
    const adm=!!(SESSAO&&SESSAO.papel==='admin');
    s.innerHTML=`<div class="nvsh"><h3>Privacidade e Conta</h3><p>Os dados são seus: pode levá-los consigo (cópia completa, acima) e pode eliminar a conta com tudo o que lhe pertence. <a href="${LEGAL_P}" target="_blank" rel="noopener">Política de privacidade</a></p></div>
      <div class="nvsb"><div class="row" style="gap:8px;flex-wrap:wrap">${adm?`<button type="button" class="btn" id="nv-uso">${ic('chart',15)} Espaço na Base de Dados</button>`:''}<button type="button" class="btn dng" id="nv-elim">${ic('trash',15)} Eliminar a Minha Conta</button></div><p class="mut peq" id="nv-bdv" style="margin:8px 0 0"></p></div>`;
    s.querySelector('#nv-elim').onclick=sbEliminarConta;const bu=s.querySelector('#nv-uso');if(bu)bu.onclick=sbUsoDlg;
    sbBdVersao().then(v=>{const el=$('#nv-bdv');if(!el||v==null)return;el.innerHTML=v>=SB_BD_MIN?'Proteções da base de dados em dia (scripts v'+v+').':'<b style="color:var(--bad)">A base de dados precisa de ser atualizada</b>'+(adm?': corra o ficheiro <b>0019_seguranca_rgpd.sql</b> no Supabase (SQL Editor). Sem ele não há limite de tentativas nos códigos das salas, limpeza diária do que expirou nem eliminação de conta.':' — avise o administrador.')}).catch(()=>{})}}catch(e){console.warn(e)}return r}}
/* o administrador é avisado (uma vez por dia) se a base de dados ainda não tiver as proteções do script 0019 */
setTimeout(function sbVigiarBd(){if(!window.__esPronto)return setTimeout(sbVigiarBd,5000);(async()=>{try{if(nvL().prov!=='supabase'||!(SESSAO&&SESSAO.papel==='admin'))return;const v=await sbBdVersao();if(v==null||v>=SB_BD_MIN)return;const hj=isoHoje();if(S.cfg.bdAviso===hj)return;S.cfg.bdAviso=hj;save();
    toast('A base de dados precisa de ser atualizada (ficheiro 0019) — Definições › Conta e Dados.','aviso')}catch(_){}})()},15000);

/* ===== 1.084: «Guardado» só quando está mesmo guardado na base de dados =====
   Antes, o indicador do cabeçalho dizia «Guardado» logo que a alteração ficava em memória; se a base de dados recusasse a gravação
   (ou a ligação falhasse sem o navegador dar por isso), nada avisava — e nesta versão não fica cópia no aparelho.
   Agora o indicador segue as partes que ainda estão por enviar: «A guardar…» → «Guardado»; se falhar, «Por guardar» a vermelho,
   nova tentativa de 15 em 15 segundos e, ao fim de 20 segundos, uma faixa com o motivo, «Tentar Agora» e «Descarregar Cópia». */
/* (não obriga a marcar já: uma gravação com alterações ainda por marcar conta como pendente) */
const sbPend=()=>{try{return (_nvMarcaPend?1:0)+Object.keys(nvL0().mod||{}).length}catch(_){return 0}};
const sbGrav={desde:0,faixa:false,ult:0,reg:''};
function sbEstadoReal(){if(!window.__esPronto||nvL0().prov!=='supabase')return null;const n=sbPend();if(!n)return 'ok';if(!navigator.onLine)return 'off';return nvL0().erro&&Date.now()-sbGrav.desde>4000?'erro':'pend'}
{const _eg=estadoGuardar;estadoGuardar=function(k){const r=sbEstadoReal();if(r==null||k==='erro')return _eg.apply(this,arguments);const el=document.getElementById('saveSt');if(!el)return;
    if(r==='ok'){_eg.call(this,'ok','Tudo guardado na base de dados');return}
    if(r==='pend'){_eg.call(this,'pend','A enviar as alterações para a base de dados');return}
    estadoPor(el,'savest erro',ic('alert',13)+(r==='off'?' Sem internet':' Por guardar'),r==='off'?'Sem internet: as alterações são guardadas quando a ligação voltar. Não feche a app.':'As últimas alterações ainda não estão na base de dados. Não feche a app.')}}
function sbFaixaGravar(mostrar){let f=document.getElementById('es-porguardar');if(!mostrar){if(f)f.remove();return}
  const off=!navigator.onLine;const motivo=off?'Sem ligação à internet.':String(nvL().erro||'A base de dados não respondeu.').slice(0,220);
  const h=`<span class="epg-t"><b>${off?'Sem internet: há alterações por guardar.':'As últimas alterações ainda não estão guardadas.'}</b> Não feche a app. <span class="epg-m">${esc(motivo)}</span></span><span class="epg-b"><button type="button" class="btn sm" id="epg-ja">Tentar Agora</button><button type="button" class="btn sm" id="epg-cp">Descarregar Cópia</button></span>`;
  if(!f){f=document.createElement('div');f.id='es-porguardar';f.setAttribute('role','alert');document.body.appendChild(f)}
  if(f.dataset.h!==h){f.dataset.h=h;f.innerHTML=h;
    f.querySelector('#epg-ja').onclick=async()=>{const b=f.querySelector('#epg-ja');b.disabled=true;b.textContent='A tentar…';try{await nvSincronizar(true)}catch(_){}sbGravTick();const b2=document.getElementById('epg-ja');if(b2){b2.disabled=false;b2.textContent='Tentar Agora'}};
    f.querySelector('#epg-cp').onclick=()=>{try{sbCopiaFicheiro()}catch(e){toast(e.message,'erro')}}}}
function sbGravTick(){const r=sbEstadoReal();if(r==null)return;try{estadoGuardar(r==='ok'?'ok':'pend')}catch(_){}
  if(r==='ok'){if(sbGrav.faixa){sbFaixaGravar(false);sbGrav.faixa=false;try{toast('Tudo guardado.','ok')}catch(_){}}sbGrav.desde=0;sbGrav.reg='';return}
  if(!sbGrav.desde)sbGrav.desde=Date.now();const ha=Date.now()-sbGrav.desde;
  if(ha>20000){sbFaixaGravar(true);sbGrav.faixa=true;const m=navigator.onLine?String(nvL().erro||'sem resposta'):'sem internet';if(sbGrav.reg!==m){sbGrav.reg=m;try{esErro('gravação','Alterações por guardar há mais de 20 s: '+m,'')}catch(_){}}}
  /* nova tentativa de 15 em 15 segundos enquanto houver alterações por guardar e houver rede */
  if(navigator.onLine&&ha>6000&&Date.now()-sbGrav.ult>15000){sbGrav.ult=Date.now();try{nvSincronizar(false).then(()=>sbGravTick()).catch(()=>{})}catch(_){}}}
setInterval(sbGravTick,1500);addEventListener('online',()=>setTimeout(sbGravTick,900));addEventListener('offline',()=>setTimeout(sbGravTick,300));
{const st=document.createElement('style');st.textContent=`html body #es-porguardar{position:fixed;left:50%;bottom:calc(14px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);z-index:99990;display:flex;align-items:center;gap:12px;flex-wrap:wrap;max-width:min(760px,calc(100vw - 24px));padding:10px 14px;background:#7f1d1d;color:#fff;font-size:13.5px;line-height:1.35;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,.35)}
html body #es-porguardar .epg-t{flex:1 1 280px}html body #es-porguardar .epg-m{opacity:.85;display:block;font-size:12.5px}html body #es-porguardar .epg-b{display:flex;gap:8px;flex-wrap:wrap}
html body #es-porguardar .btn{background:#fff;color:#7f1d1d;border-color:#fff}html body.est-sge #es-porguardar,html body.est-sge #es-porguardar .btn{border-radius:0}
@media print{html body #es-porguardar{display:none}}`;document.head.appendChild(st)}

/* ===== Frase secreta (opcional): a chave dos dados deixa de ficar legível na base de dados =====
   Por omissão, a chave fica na conta (linha «conta-chave») para os dados abrirem em qualquer aparelho só com a entrada Google — quem
   administra a base de dados consegue lê-la. Com a frase secreta, a linha passa a guardar a chave EMBRULHADA: cifrada (AES-256-GCM)
   com uma chave tirada da frase (PBKDF2-SHA-256, 600 000 voltas). A frase nunca sai do aparelho. Em cada aparelho novo (ou depois de
   terminar a sessão) pede-se a frase ou a chave de recuperação. Quem perder as duas perde os dados: ninguém os consegue recuperar.
   Linha: {v:2, w:{s,i,iv,c}, h, salt, q} — sem «k». «h» = princípio do SHA-256 da chave, para saber se o embrulho é o da chave atual.
   A cópia do embrulho fica também nas definições cifradas (S.cfg.fraseW/fraseH): se um aparelho com uma versão antiga da app voltar a
   gravar a chave em claro, o primeiro aparelho atualizado repõe o embrulho sozinho. */
const SB_FR_VOLTAS=600000;
async function sbFraseKek(frase,s,i){const m=await crypto.subtle.importKey('raw',new TextEncoder().encode(String(frase).normalize('NFKC')),'PBKDF2',false,['deriveKey']);
  return crypto.subtle.deriveKey({name:'PBKDF2',salt:unb64(s),iterations:i,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function sbFraseH(k){const d=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode('eduspruce-chave:'+k)));return [...d.slice(0,8)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function sbFraseEmbrulhar(frase,k){const s=b64(crypto.getRandomValues(new Uint8Array(16))),iv=crypto.getRandomValues(new Uint8Array(12));const kek=await sbFraseKek(frase,s,SB_FR_VOLTAS);
  const c=await crypto.subtle.encrypt({name:'AES-GCM',iv},kek,new TextEncoder().encode(k));return {s,i:SB_FR_VOLTAS,iv:b64(iv),c:b64(c)}}
async function sbFraseAbrir(frase,w){const kek=await sbFraseKek(frase,w.s,Math.min(Math.max(+w.i||SB_FR_VOLTAS,100000),5000000));
  try{return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(w.iv)},kek,unb64(w.c)))}catch(_){return null}}
const sbFraseLinha=j=>!!(j&&j.w&&j.w.c&&!j.k);
async function sbLinhaChave(p,D){try{const t=D&&Object.prototype.hasOwnProperty.call(D,SB_CH)?D[SB_CH]:await p.ler(SB_CH);return t?JSON.parse(t):null}catch(_){return null}}
/* a chave abre mesmo os dados desta conta? (confirma com a marca do manifesto) */
async function sbChaveAbre(p,k,D){if(!k)return false;let man=null;try{const n=NV_PREF+'manifest.json';const t=D&&Object.prototype.hasOwnProperty.call(D,n)?D[n]:await p.ler(n);man=t?JSON.parse(t):null}catch(_){}
  if(!man||!man.chk)return true;try{const ck=await crypto.subtle.importKey('raw',unb64(k),'AES-GCM',false,['decrypt']);return await nvDecifrar(man.chk,ck)==='eduflow'}catch(_){return false}}
const sbFraseReg=(w,h,salt)=>JSON.stringify({v:2,w,h,salt:salt||'',q:Date.now()});
async function sbFraseLimparHist(){try{await sbRpc('eduspruce_chave_hist_limpar');return true}catch(_){return false}}
/* ligar: embrulha, grava, relê e confirma que a frase abre — só depois dá por feito; se algo falhar, a linha volta ao que era */
async function sbFraseAtivar(frase){const L=nvL();if(L.prov!=='supabase'||!L.k)throw new Error('A chave ainda não está disponível neste aparelho.');const p=await sbObter();
  if(!(await sbChaveAbre(p,L.k)))throw new Error('A chave deste aparelho não abre os dados da conta. Recarregue a página e tente de novo.');
  const antes=await p.ler(SB_CH);const w=await sbFraseEmbrulhar(frase,L.k),h=await sbFraseH(L.k);
  try{if(antes!=null)await p.escrever(SB_CH,sbFraseReg(w,h,L.salt));else await p.criar(SB_CH,sbFraseReg(w,h,L.salt));
    const j=await sbLinhaChave(p);if(!sbFraseLinha(j)||(await sbFraseAbrir(frase,j.w))!==L.k)throw new Error('A verificação depois de gravar falhou.')}
  catch(e){try{await p.escrever(SB_CH,antes||JSON.stringify({v:1,k:L.k,salt:L.salt||'',q:Date.now()}))}catch(_){}throw new Error('Não foi possível ligar a frase secreta ('+(e.message||'erro')+'). Nada mudou.')}
  S.cfg.fraseW=w;S.cfg.fraseH=h;S.cfg.fraseEm=Date.now();save();const limpo=await sbFraseLimparHist();try{audit('Segurança','Frase secreta ligada','A chave dos dados deixou de ficar legível na base de dados')}catch(_){}return {limpo}}
async function sbFraseDesligar(){const L=nvL();if(L.prov!=='supabase'||!L.k)throw new Error('A chave ainda não está disponível neste aparelho.');const p=await sbObter();
  await p.escrever(SB_CH,JSON.stringify({v:1,k:L.k,salt:L.salt||'',q:Date.now()}));delete S.cfg.fraseW;delete S.cfg.fraseH;delete S.cfg.fraseEm;save();nvSet({kConta:1});try{audit('Segurança','Frase secreta desligada','A chave voltou a ficar guardada na conta')}catch(_){}}
/* nenhum caminho automático volta a gravar a chave em claro enquanto a frase estiver ligada */
{const _gc=sbGuardarChaveNaConta;sbGuardarChaveNaConta=async function(){const L=nvL();if(L.prov!=='supabase'||!L.k)return;const p=await sbObter();const j=await sbLinhaChave(p);const h=await sbFraseH(L.k);
    if(sbFraseLinha(j)){/* a linha já está embrulhada: fica como está (e este aparelho fica a saber) */if(j.h===h&&window.__esPronto&&S.cfg&&!S.cfg.fraseW){S.cfg.fraseW=j.w;S.cfg.fraseH=h;save()}nvSet({kConta:1,kDe:sbEmailApp()||L.kDe||''});return}
    if(window.__esPronto&&S.cfg&&S.cfg.fraseW){if(S.cfg.fraseH===h){/* um aparelho com uma versão antiga repôs a chave em claro: volta o embrulho */await p.escrever(SB_CH,sbFraseReg(S.cfg.fraseW,h,L.salt));nvSet({kConta:1,kDe:sbEmailApp()||L.kDe||''});await sbFraseLimparHist();try{audit('Segurança','Frase secreta reposta na conta','Outro aparelho tinha voltado a gravar a chave')}catch(_){}return}
      /* a chave mudou e o embrulho já não lhe corresponde: sem a frase não se refaz — desliga-se, para os dados nunca ficarem fechados */delete S.cfg.fraseW;delete S.cfg.fraseH;save();try{toast('A frase secreta foi desligada porque a chave dos dados mudou. Ligue-a de novo em Definições › Conta e Dados.','aviso')}catch(_){}}
    return _gc.apply(this,arguments)}}
{const _ur=sbUsarChaveRec;sbUsarChaveRec=async function(p,pf,k,salt){const j=await sbLinhaChave(p);if(!sbFraseLinha(j))return _ur.apply(this,arguments);
    if(!(await sbChaveAbre(p,k)))return false;try{_nvK=null}catch(_){}nvSet({k,salt:salt||j.salt||'',kDe:pf.email,kConta:1,base:null,mod:{}});return true}}
{const _ca=sbChaveAuto;sbChaveAuto=async function(p,pf,D){const j=await sbLinhaChave(p,D);if(!sbFraseLinha(j))return _ca.apply(this,arguments);
    const L0=nvL();if(L0.k&&L0.kDe&&L0.kDe!==pf.email){try{_nvK=null}catch(_){}nvSet({k:null,salt:null,kDe:'',kConta:0,base:null,mod:{}})}
    const L=nvL();if(L.k&&await sbChaveAbre(p,L.k,D)){nvSet({kDe:pf.email,kConta:1});return}
    const e=new Error('Esta conta está protegida com frase secreta.');e.semChave=true;throw e}}
/* aparelho novo (ou sessão terminada): pede a frase ou a chave de recuperação */
function sbPedirFrase(p,pf){return new Promise(res=>{const d=document.createElement('dialog');d.className='nvmc sbcod';d.setAttribute('aria-labelledby','sbf-t');
  d.innerHTML=`<form class="nvmcf" autocomplete="off" data-nosub><h2 id="sbf-t">${ic('cadeado',18)} Frase secreta</h2>
    <p class="hint">Esta conta está protegida com uma <b>frase secreta</b>. Escreva-a para abrir os seus dados neste aparelho.</p>
    <label for="sbf-1">Frase secreta ou chave de recuperação</label><input type="password" id="sbf-1" autocomplete="current-password" autocapitalize="none" spellcheck="false">
    <div class="nverr" id="sbf-e" role="alert"></div>
    <div class="row" style="gap:8px;justify-content:flex-end;margin-top:8px;flex-wrap:wrap"><button type="button" class="btn" id="sbf-s">Terminar Sessão</button><button type="submit" class="btn pri" id="sbf-ok">${ic('check',15)} Abrir os Meus Dados</button></div>
    <p class="hint sbcalt">${ic('info',14)}<span><b>Não se lembra da frase?</b> Cole aqui a chave de recuperação (o texto que começa por EDUSPRUCE-CHAVE), ou desligue a frase num aparelho onde a app ainda esteja aberta. Sem a frase e sem a chave de recuperação, ninguém consegue abrir os dados.</span></p></form>`;
  document.body.appendChild(d);d.addEventListener('cancel',e=>e.preventDefault());d.addEventListener('keydown',e=>e.stopPropagation());try{d.showModal()}catch(_){d.setAttribute('open','')}
  const er=d.querySelector('#sbf-e'),inp=d.querySelector('#sbf-1'),okb=d.querySelector('#sbf-ok');setTimeout(()=>inp.focus(),60);let fechado=false,falhas=0;
  const fim=v=>{if(fechado)return;fechado=true;clearInterval(t);try{d.close()}catch(_){}d.remove();res(v)};
  /* se, entretanto, a frase for desligada noutro aparelho, continua sozinho */
  const t=setInterval(async()=>{try{const j=await sbLinhaChave(p);if(j&&j.k){await sbChaveAuto(p,pf);fim(true)}}catch(_){}},5000);
  d.querySelector('#sbf-s').onclick=()=>{fim(false);sbTerminar()};
  d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();er.textContent='';const c=inp.value;if(!c){er.textContent='Escreva a frase secreta.';return}okb.disabled=true;
    try{const rk=c.replace(/\s+/g,'').match(/^EDUSPRUCE-CHAVE\.([A-Za-z0-9+/=]+)\.([A-Za-z0-9+/=]*)$/i);
      if(rk){if(await sbUsarChaveRec(p,pf,rk[1],rk[2])){try{audit('Conta','Dados abertos com a chave de recuperação','')}catch(_){}return fim(true)}er.textContent='Esta chave de recuperação não abre os dados desta conta.';okb.disabled=false;return}
      const j=await sbLinhaChave(p);if(!sbFraseLinha(j)){await sbChaveAuto(p,pf);return fim(true)}
      const k=await sbFraseAbrir(c,j.w);if(k&&await sbChaveAbre(p,k)){try{_nvK=null}catch(_){}nvSet({k,salt:j.salt||'',kDe:pf.email,kConta:1,base:null,mod:{}});return fim(true)}
      falhas++;/* cada tentativa errada espera mais um pouco */await new Promise(r=>setTimeout(r,Math.min(8000,500*falhas)));er.textContent='Frase errada. Tente de novo.';okb.disabled=false;inp.select()}
    catch(e2){okb.disabled=false;er.textContent=e2.message||'Não foi possível abrir.'}})})}
{const _pc=sbPedirCodigoAntigo;sbPedirCodigoAntigo=async function(p,pf){const j=await sbLinhaChave(p);if(sbFraseLinha(j))return sbPedirFrase(p,pf);return _pc.apply(this,arguments)}}
/* Definições › Conta e Dados › Privacidade e Conta */
function sbFraseDlg(){const L=nvL();if(!L.k)return toast('A chave ainda não está disponível neste aparelho.','erro');const d=document.createElement('dialog');d.className='nvmc';d.setAttribute('aria-labelledby','sfd-t');
  d.innerHTML=`<form class="nvmcf" autocomplete="off" data-nosub><h2 id="sfd-t">${ic('cadeado',18)} Frase secreta</h2>
    <p class="hint">Hoje a chave dos seus dados fica guardada na conta, para tudo abrir só com a entrada Google. Com uma frase secreta, a chave fica na base de dados <b>fechada com a sua frase</b>: nem quem administra a base de dados a consegue ler.</p>
    <p class="hint"><b>O que muda:</b> em cada aparelho novo, e sempre que terminar a sessão, a app pede a frase. <b>Se perder a frase e a chave de recuperação, ninguém consegue recuperar os dados.</b></p>
    <label for="sfd-1">Frase secreta (12 caracteres ou mais — várias palavras é o ideal)</label><input type="password" id="sfd-1" autocomplete="new-password" autocapitalize="none" spellcheck="false">
    <label for="sfd-2">Repita a frase</label><input type="password" id="sfd-2" autocomplete="new-password" autocapitalize="none" spellcheck="false">
    <div class="row" style="gap:8px;flex-wrap:wrap;margin-top:6px"><button type="button" class="btn" id="sfd-k">${ic('download',15)} Descarregar a Chave de Recuperação</button></div>
    <label style="display:flex;gap:8px;align-items:flex-start;margin-top:6px"><input type="checkbox" id="sfd-c" style="margin-top:3px"><span>Guardei a chave de recuperação num sítio seguro e sei que, sem a frase e sem essa chave, os dados não se recuperam.</span></label>
    <div class="nverr" id="sfd-e" role="alert"></div>
    <div class="row" style="gap:8px;justify-content:flex-end;margin-top:8px;flex-wrap:wrap"><button type="button" class="btn" id="sfd-x">Cancelar</button><button type="submit" class="btn pri" id="sfd-ok" disabled>${ic('check',15)} Ligar a Frase Secreta</button></div></form>`;
  document.body.appendChild(d);try{d.showModal()}catch(_){d.setAttribute('open','')}const q=s=>d.querySelector(s);const er=q('#sfd-e'),ok=q('#sfd-ok');let desc=false;
  const fecha=()=>{try{d.close()}catch(_){}d.remove()};d.addEventListener('cancel',e=>{e.preventDefault();fecha()});d.addEventListener('keydown',e=>e.stopPropagation());
  const ve=()=>{ok.disabled=!(desc&&q('#sfd-c').checked)};q('#sfd-c').onchange=ve;q('#sfd-x').onclick=fecha;
  q('#sfd-k').onclick=()=>{const t=sbChaveRecTxt();const em=sbEmailApp()||nvL().kDe||'';download('EduSpruce-chave-de-recuperacao.txt',`EduSpruce — chave de recuperação\nConta: ${em}\nCriada em: ${new Date().toLocaleString('pt-PT')}\n\n${t}\n\nComo usar: entre na EduSpruce com a conta Google; quando a app pedir a frase secreta, cole esta chave.\nGuarde num sítio seguro e não partilhe.`,'text/plain');S.cfg.chaveRecGuardada=Date.now();save();desc=true;ve()};
  q('form').addEventListener('submit',async e=>{e.preventDefault();er.textContent='';const a=q('#sfd-1').value,b=q('#sfd-2').value;
    if(a.length<12){er.textContent='A frase tem de ter pelo menos 12 caracteres.';return}if(a!==b){er.textContent='As duas frases não são iguais.';return}if(/^EDUSPRUCE-CHAVE\./i.test(a.trim())){er.textContent='A frase não pode ser a chave de recuperação.';return}
    ok.disabled=true;ok.textContent='A ligar…';try{const r=await sbFraseAtivar(a);fecha();try{bindNvPainel()}catch(_){}
      avisoModal('Frase secreta ligada',['A chave dos seus dados deixou de ficar legível na base de dados.','Neste aparelho continua tudo aberto; nos outros, a app pede a frase na próxima vez que entrar.',r.limpo?'A cópia antiga da chave foi apagada do histórico.':'A cópia antiga da chave sai do histórico da base de dados dentro de 30 dias, no máximo.'],[{t:ic('check',15)+' Entendido',c:'pri',v:1}])}
    catch(e2){ok.disabled=false;ok.innerHTML=ic('check',15)+' Ligar a Frase Secreta';er.textContent=e2.message||'Não foi possível ligar.'}})}
async function sbFraseDesligarDlg(){const v=await avisoModal('Desligar a frase secreta?',['A chave dos dados volta a ficar guardada na conta: os dados abrem em qualquer aparelho só com a entrada Google.','Quem administra a base de dados volta a conseguir ler a chave.'],[{t:'Desligar',c:'dng',v:1},{t:'Cancelar',c:'pri',v:0}]);if(!v)return;
  try{await sbFraseDesligar();toast('Frase secreta desligada','ok');try{bindNvPainel()}catch(_){}}catch(e){toast(e.message||'Não foi possível desligar.','erro')}}
{const _bF=bindNvPainel;bindNvPainel=function(){const r=_bF.apply(this,arguments);try{const s=$('#nv-rgpd');if(s&&nvL().prov==='supabase'){let b=s.querySelector('#nv-frase-l');if(b)b.remove();const on=!!(S.cfg&&S.cfg.fraseW);
    const div=document.createElement('div');div.id='nv-frase-l';div.style.margin='0 0 12px';div.innerHTML=`<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center"><button type="button" class="btn" id="nv-frase">${ic('cadeado',15)} ${on?'Desligar a Frase Secreta':'Frase Secreta…'}</button><span class="mut peq">${on?'<b>Frase secreta ligada</b>'+(S.cfg.fraseEm?' desde '+new Date(S.cfg.fraseEm).toLocaleDateString('pt-PT'):'')+': a chave dos dados não fica legível na base de dados.':'Opcional: fecha a chave dos dados com uma frase só sua. Sem ela, a chave fica guardada na conta.'}</span></div>`;
    const ref=s.querySelector('.nvsb');if(ref)ref.prepend(div);else s.appendChild(div);div.querySelector('#nv-frase').onclick=on?sbFraseDesligarDlg:sbFraseDlg}}catch(e){console.warn(e)}return r}}
/* ao abrir: confirma que a linha da conta condiz com a escolha (repõe o embrulho se um aparelho antigo o desfez) */
setTimeout(function sbFraseVigiar(){if(!window.__esPronto)return setTimeout(sbFraseVigiar,5000);(async()=>{try{const L=nvL();if(L.prov!=='supabase'||!L.k)return;const p=await sbObter();const j=await sbLinhaChave(p);
    if(sbFraseLinha(j)||(S.cfg&&S.cfg.fraseW))await sbGuardarChaveNaConta()}catch(e){console.warn('[EduSpruce] frase secreta:',e.message)}})()},9000);

/* ===================== Autoavaliação dos alunos pelo telemóvel (QR code ou link + código) =====================
   O professor abre uma sessão temporária (turma + período); o aluno aponta o telemóvel ao QR code (ou abre o link e escreve o código),
   escolhe o seu número e faz a autoavaliação. As respostas chegam sozinhas ao Perfil de Aprendizagem de cada aluno.
   Tudo vai cifrado com uma chave que sai do código: a base de dados nunca vê nomes nem respostas. Pode desligar-se nas Definições. */
const AA_ALF='23456789ABCDEFGHJKMNPQRSTUVWXYZ';
const aaLigado=()=>S.cfg.autoavTlm!==false;
const aaHex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
async function aaChaves(code){const te=new TextEncoder();const id=aaHex(await crypto.subtle.digest('SHA-256',te.encode('es-aa-id:'+code))).slice(0,40);
  const base=await crypto.subtle.importKey('raw',te.encode(code),'PBKDF2',false,['deriveKey']);
  const k=await crypto.subtle.deriveKey({name:'PBKDF2',salt:te.encode('es-aa-k:'+id),iterations:150000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);return {id,k}}
const _aaK=new Map();async function aaCh(code){if(!_aaK.has(code))_aaK.set(code,aaChaves(code));return _aaK.get(code)}
async function aaCifrar(o,k){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(JSON.stringify(o)));return 'A1.'+b64(iv)+'.'+b64(ct)}
/* 1.084 · tudo o que os alunos enviam passa pelo esLimpo (app/051-utilitarios.js) antes de ser usado */
async function aaDecifrar(s,k){const p=String(s).split('.');const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(p[1])},k,unb64(p[2]));return esLimpo(JSON.parse(new TextDecoder().decode(pt)))}
function aaCodigo(n){n=n||8;const o=[];while(o.length<n){const b=crypto.getRandomValues(new Uint8Array(16));for(const x of b){if(x<248&&o.length<n)o.push(AA_ALF[x%31])}}return o.join('')}
/* v0.942 · papel para o ano todo: cada turma tem um código fixo e cada aluno o seu código pessoal (vão no QR code do papel de cada aluno) */
const aaAtivos=t=>t.alunos.filter(a=>a.frequenta!==false).sort((a,b)=>(+a.num||0)-(+b.num||0));
function aaTurmaCod(t){if(!t.autoavCod){t.autoavCod=aaCodigo(8);t.autoavCodQ=Date.now();t.autoavCh={};t.autoavImp=[];save()}return t.autoavCod}
function aaChave(t,aid){t.autoavCh=t.autoavCh||{};if(!t.autoavCh[aid]){t.autoavCh[aid]=aaCodigo(5);save()}return t.autoavCh[aid]}
const aaUrlAluno=(t,a)=>aaUrl(aaTurmaCod(t))+'.'+a.id+'.'+aaChave(t,a.id);
const _aaVers=new Map();
const aaFmt=c=>c.slice(0,4)+'-'+c.slice(4);
const aaUrl=c=>location.origin+location.pathname.replace(/[^/]*$/,'')+'aluno.html#'+c;
const aaCurto=n=>{const p=String(n||'').trim().split(/\s+/);return p.length>1?p[0]+' '+p[p.length-1][0]+'.':p[0]||''};
const aaErro=e=>{const m=(e&&e.message)||String(e);if(/does not exist|schema cache|PGRST20[25]|42P01/i.test(m+(e&&e.code||'')))return 'A base de dados ainda não está preparada para a autoavaliação pelo telemóvel. O administrador tem de correr uma vez o script «0004_autoavaliacao_alunos.sql» no Supabase.';return m};
const aaSb=async()=>(await sbObter()).cliente;
const aaSess=t=>{t.autoavTlm=Array.isArray(t.autoavTlm)?t.autoavTlm:[];return t.autoavTlm};
async function aaQrLib(){if(window.qrcode)return;await new Promise((ok,ko)=>{const s=document.createElement('script');s.src='esm/qrcode-1.4.4.min.js';s.onload=ok;s.onerror=()=>ko(new Error('Não foi possível carregar o gerador de QR code.'));document.head.appendChild(s)})}
function aaQR(txt){const q=window.qrcode(0,'M');q.addData(txt);q.make();const n=q.getModuleCount(),m=2;let d='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(q.isDark(y,x))d+=`M${x+m} ${y+m}h1v1h-1z`;
  return `<svg viewBox="0 0 ${n+2*m} ${n+2*m}" role="img" aria-label="QR code da autoavaliação" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path d="${d}" fill="#000"/></svg>`}
/* abrir uma sessão */
async function aaAbrir(t,p,q,min,pes){pes=pes===undefined?(t.autoavModo!=='geral'):!!pes;for(const s0 of [...aaSess(t)]){try{await aaFechar(t,s0)}catch(_){}}const code=aaTurmaCod(t);aaAtivos(t).forEach(a=>aaChave(t,a.id));const {id,k}=await aaCh(code);const sec=isSec(t);
  const D={v:2,pes:pes?1:0,t:t.nome,d:t.disciplina,p,pn:perNome(p),W:perW(),esc:sec?'20':'5',prof:S.cfg.professor||'',q,dom:(t.dominios||[]).map(d=>({id:d.id,n:d.nome})),
    al:t.alunos.filter(a=>a.frequenta!==false).sort((a,b)=>(+a.num||0)-(+b.num||0)).map(a=>({id:a.id,n:a.num||'',nm:aaCurto(a.nome)}))};
  const expira=new Date(Date.now()+min*60000).toISOString();const sb=await aaSb();
  const linha={id,dados:await aaCifrar(D,k),expira};let r=await sb.from('eduspruce_autoav').insert(linha);
  if(r.error&&(r.error.code==='23505'||/duplicate key/i.test(r.error.message||''))){await sb.from('eduspruce_autoav').delete().eq('id',id);r=await sb.from('eduspruce_autoav').insert(linha)}
  if(r.error)throw new Error(aaErro(r.error));
  const s={code,p,pes:pes?1:0,q,criado:Date.now(),expira:Date.parse(expira),n:0,vistos:[],esc:{}};aaSess(t).push(s);save();try{audit('Avaliação','Autoavaliação pelo telemóvel aberta',t.nome+' · '+perNome(p))}catch(_){}return s}
/* trazer as respostas para o Perfil de Aprendizagem */
async function aaImportar(t,s){const {id,k}=await aaCh(s.code);const sb=await aaSb();const r=await sb.from('eduspruce_autoav_resp').select('id,conteudo').eq('sessao',id).order('id');
  if(r.error)throw new Error(aaErro(r.error));const ult={},V={},rej=[];s.esc=s.esc||{};
  for(const x of r.data||[]){try{const o=await aaDecifrar(x.conteudo,k);if(!o||Array.isArray(o))continue;o.aid=esIdOk(o.aid);o.q=esNumOk(o.q);o.n=esTxtOk(o.n,12);o.k=esTxtOk(o.k,60);if(!o.aid)continue;
    if(s.pes&&(!o.k||o.k!==((t.autoavCh||{})[o.aid]))){rej.push({aid:o.aid,n:o.n,q:o.q});continue}
    (V[o.aid]=V[o.aid]||[]).push(o)}catch(_){}}
  Object.keys(V).forEach(aid=>{const L=V[aid].sort((a,b)=>a.q-b.q);const esc=s.esc[aid];ult[aid]=(esc&&L.find(o=>o.q===esc))||L[L.length-1]});
  _aaVers.set(s.code,V);s.rej=rej.map(x=>({n:x.n,q:x.q}));s.dup=Object.keys(V).filter(aid=>V[aid].length>1);
  /* sugestões para as aulas: guardadas sem o nome do aluno (só uma marca para substituir se o aluno corrigir) */
  {t.autoavSug=Array.isArray(t.autoavSug)?t.autoavSug:[];let mud=false;for(const aid in ult){const o=ult[aid];const txt=String(o.sug||'').trim().slice(0,800);const h=nvHash(aid+'|'+s.code+'|'+s.p+'|'+(s.criado||0));const i=t.autoavSug.findIndex(x=>x.h===h);
      if(!txt){if(i>=0){t.autoavSug.splice(i,1);mud=true}continue}if(i>=0){if(t.autoavSug[i].txt!==txt){t.autoavSug[i]={...t.autoavSug[i],txt,q:o.q};mud=true}}else{t.autoavSug.push({h,p:s.p,q:o.q,txt});mud=true}}if(mud)save()}
  let novos=0;const vis=new Set(s.vistos||[]);
  for(const aid in ult){const a=t.alunos.find(z=>z.id===aid);if(!a)continue;const o=ult[aid];const AV=autoD(a,s.p);if(AV.alunoQ===o.q){vis.add(aid);continue}
    const dom={};(t.dominios||[]).forEach(d=>{const v=+((o.dom||{})[d.id]);if(v>=1&&v<=4)dom[d.id]=v});
    Object.assign(AV.dom,dom);if(o.nota)AV.nota=String(o.nota).slice(0,5);if(o.forte)AV.forte=String(o.forte).slice(0,600);if(o.melhorar)AV.melhorar=String(o.melhorar).slice(0,600);
    const pl=o.plano||{};AV.plano=AV.plano||{};['meta','estr','apoio'].forEach(c=>{if(pl[c])AV.plano[c]=String(pl[c]).slice(0,600)});
    if(AV.nota){a.autoav=a.autoav||{};a.autoav[s.p]=AV.nota}AV.data=isoHoje();AV.origem='aluno';AV.alunoQ=o.q;vis.add(aid);novos++}
  s.vistos=[...vis];s.n=s.vistos.length;if(novos)save();return novos}
async function aaFechar(t,s){try{await aaImportar(t,s)}catch(_){}const {id}=await aaCh(s.code);const sb=await aaSb();const rd=await sb.from('eduspruce_autoav').delete().eq('id',id);if(rd&&rd.error)throw new Error(aaErro(rd.error));
  const L=aaSess(t);const i=L.indexOf(s);if(i>=0)L.splice(i,1);save()}
async function aaMais(t,s,min){const {id}=await aaCh(s.code);const sb=await aaSb();const ex=new Date(Math.max(Date.now(),s.expira)+min*60000);const r=await sb.from('eduspruce_autoav').update({expira:ex.toISOString()}).eq('id',id);if(r.error)throw new Error(aaErro(r.error));s.expira=+ex;save()}
/* ao abrir a app: traz respostas que chegaram entretanto e arruma as sessões que já expiraram */
async function aaVerificarTodas(){if(!window.__esPronto)return;const a=A();if(!a)return;for(const t of a.turmas){for(const s of [...aaSess(t)]){try{const n=await aaImportar(t,s);if(n)toast(n+' autoavaliação(ões) recebida(s) · '+t.nome,'ok');if(Date.now()>s.expira)await aaFechar(t,s)}catch(e){console.warn('[EduSpruce] autoavaliação:',e.message)}}}}
setTimeout(function aaCiclo(){aaVerificarTodas().finally(()=>setTimeout(aaCiclo,120000))},8000);

/* janela do professor */
function aaSugHtml(t,p){const L=(Array.isArray(t.autoavSug)?t.autoavSug:[]).filter(x=>!p||x.p===p).sort((a,b)=>b.q-a.q);
  if(!L.length)return `<p class="mut aasugv">Ainda não há sugestões${p?' neste '+esc(perW().toLowerCase()):''}.</p>`;
  return `<ul class="aasugl">${L.map(x=>`<li><span>${esc(x.txt)}</span><small class="mut">${esc(perNome(x.p))} · ${new Date(x.q).toLocaleDateString('pt-PT',{day:'numeric',month:'short'})}</small></li>`).join('')}</ul>`}
/* folha com um papel por aluno (QR code pessoal + código), para recortar; serve o ano todo */
async function aaFolha(t,soNovos){await aaQrLib();const cod=aaTurmaCod(t);let L=aaAtivos(t);const imp=new Set(t.autoavImp||[]);if(soNovos)L=L.filter(a=>!imp.has(a.id));
  if(!L.length)return toast('Não há alunos novos para imprimir.','aviso');
  const host=location.host||'eduspruce.pt';$$('#aafolha').forEach(x=>x.remove());const f=document.createElement('div');f.id='aafolha';
  f.innerHTML=`<div class="aaf-bar"><b>${ic('printer',16)} Papéis da autoavaliação · ${esc(t.nome)} · ${esc(t.disciplina)}</b><span class="mut">${L.length} aluno${L.length>1?'s':''} · recorte pelas linhas · cada aluno guarda o seu para o ano todo</span><span class="sp1"></span><button type="button" class="btn pri" id="aaf-imp">${ic('printer',15)} Imprimir</button><button type="button" class="btn" id="aaf-x">Fechar</button></div>
    <div class="aaf-g">${L.map(a=>`<div class="aaf-p"><div class="aaf-q">${aaQR(aaUrlAluno(t,a))}</div><div class="aaf-t"><div class="aaf-k">Autoavaliação · ${esc(t.disciplina)}</div><div class="aaf-n">N.º ${esc(a.num||'')} · ${esc(aaCurto(a.nome))}</div><div class="aaf-c">${esc(t.nome)}</div>
      <div class="aaf-i">Aponta a câmara ao código. Sem câmara: <b>${esc(host)}/aluno.html</b> · turma <b>${esc(aaFmt(cod))}</b> · o teu código <b class="aaf-pc">${esc(aaChave(t,a.id))}</b></div><div class="aaf-g2">Guarda este papel: serve para todas as autoavaliações deste ano. Não o mostres aos colegas.</div></div></div>`).join('')}</div>`;
  const dl=[...document.querySelectorAll('dialog.aadlg[open]')];dl.forEach(x=>{try{x.close()}catch(_){}});
  document.body.appendChild(f);document.body.classList.add('aa-folha');
  const sai=()=>{f.remove();document.body.classList.remove('aa-folha');dl.forEach(x=>{if(x.isConnected)try{x.showModal()}catch(_){}})};f.querySelector('#aaf-x').onclick=sai;
  f.querySelector('#aaf-imp').onclick=()=>{t.autoavImp=[...new Set([...(t.autoavImp||[]),...L.map(a=>a.id)])];save();setTimeout(()=>window.print(),60)};
  try{audit('Avaliação','Papéis da autoavaliação gerados',t.nome+' · '+L.length+' aluno(s)')}catch(_){}}
async function aaPainel(){const t=T();if(!t)return toast('Escolha primeiro uma turma.','erro');if(!aaLigado())return toast('A autoavaliação pelo telemóvel está desligada (Definições › Módulos Opcionais).','erro');
  if(!window.__esPronto)return toast('Os dados ainda estão a abrir. Tente dentro de momentos.','erro');
  $$('dialog.aadlg').forEach(d=>d.remove());const d=document.createElement('dialog');d.className='aadlg';d.setAttribute('aria-labelledby','aa-t');document.body.appendChild(d);
  let tm=null;const fim=()=>{clearInterval(tm);try{d.close()}catch(_){}d.remove();if(VIEW)try{go(VIEW)}catch(_){}};
  d.addEventListener('cancel',e=>{e.preventDefault();fim()});
  const ativos=aaAtivos(t);
  const formulario=(msg)=>{clearInterval(tm);const np=periodos().length||3,pa=perAtual(t);const imp=new Set(t.autoavImp||[]);const novos=t.autoavCod?ativos.filter(a=>!imp.has(a.id)).length:ativos.length;
    d.innerHTML=`<form class="aaw" data-nosub><header class="aah"><h2 id="aa-t">${ic('users',18)} Autoavaliação pelo Telemóvel</h2><button type="button" class="btn ico" id="aa-x" aria-label="Fechar">${ic('x',16)}</button></header>
      <p class="mut">${esc(t.nome)} · ${esc(t.disciplina)} · ${ativos.length} alunos. Cada aluno tem um <b>papel com o seu QR code</b>, para o ano todo. Quando abrir a autoavaliação, os alunos apontam a câmara ao seu papel e respondem; só cada aluno consegue responder por si. As respostas aparecem no <b>Perfil de Aprendizagem</b>.</p>
      <section class="aabox"><h3>${ic('printer',15)} 1. Papéis dos alunos (imprimir uma vez)</h3>
        <p class="mut" style="margin:0 0 8px">${t.autoavCod?`Código da turma <b>${esc(aaFmt(t.autoavCod))}</b> · criado a ${esc(new Date(t.autoavCodQ||Date.now()).toLocaleDateString('pt-PT'))}${novos?` · <b>${novos}</b> aluno${novos>1?'s':''} ainda sem papel impresso`:' · todos os alunos têm papel'}`:'Ainda não foram criados os papéis desta turma.'}</p>
        <div class="row aaa"><button type="button" class="btn" id="aa-fol">${ic('printer',15)} ${t.autoavCod?'Imprimir os Papéis':'Criar e Imprimir os Papéis'}</button>${t.autoavCod&&novos&&novos<ativos.length?`<button type="button" class="btn" id="aa-foln">Imprimir Só os Novos (${novos})</button>`:''}${t.autoavCod?`<button type="button" class="btn" id="aa-reg" title="Os papéis antigos deixam de funcionar">${ic('refresh',15)} Códigos Novos</button>`:''}</div></section>
      <section class="aabox"><h3>${ic('sparkle',15)} 2. Abrir a autoavaliação</h3>
      <div class="aag"><div><label for="aa-p">${esc(perW())}</label><select id="aa-p">${Array.from({length:np},(_,i)=>`<option value="${i+1}" ${i+1===pa?'selected':''}>${esc(perNome(i+1))}</option>`).join('')}</select></div>
      <div><label for="aa-m">Fica aberta durante</label><select id="aa-m"><option value="20">20 minutos</option><option value="45" selected>45 minutos</option><option value="90">90 minutos</option><option value="1440">24 horas</option><option value="4320">3 dias</option><option value="10080">7 dias</option></select></div></div>
      <fieldset class="aaq"><legend>O que os alunos respondem</legend>
        <label class="chk"><input type="checkbox" id="aa-qd" checked> Nível em cada domínio (1 a 4)</label>
        <label class="chk"><input type="checkbox" id="aa-qn" checked> Classificação que propõem</label>
        <label class="chk"><input type="checkbox" id="aa-qr" checked> O que fizeram bem e o que podem melhorar</label>
        <label class="chk"><input type="checkbox" id="aa-qp" checked> Compromisso para o próximo ${esc(perW().toLowerCase())}</label>
        <label class="chk"><input type="checkbox" id="aa-qs" checked> Sugestões para as aulas <span class="mut">(aparecem aqui sem o nome do aluno)</span></label></fieldset>
      <fieldset class="aaq"><legend>Como os alunos se identificam</legend>
        <label class="chk"><input type="radio" name="aa-modo" value="pes" ${t.autoavModo!=='geral'?'checked':''}> <span><b>Com o código pessoal</b> do papel <span class="mut">— só o próprio aluno pode responder por si</span></span></label>
        <label class="chk"><input type="radio" name="aa-modo" value="geral" ${t.autoavModo==='geral'?'checked':''}> <span><b>Só com o código da turma</b> <span class="mut">— cada aluno escolhe o seu número, sem código pessoal (confia que escolhe o certo)</span></span></label></fieldset>
      <p class="nverr" role="alert">${esc(msg||'')}</p>
      <div class="row aaa"><button type="button" class="btn" id="aa-c">Cancelar</button><button type="button" class="btn pri" id="aa-ok">${ic('sparkle',15)} Abrir a Autoavaliação</button></div></section>
      <details class="aabox"><summary><b>${ic('chat',15)} Sugestões dos alunos para as aulas</b> <span class="mut">(${(t.autoavSug||[]).length})</span></summary>${aaSugHtml(t,0)}</details>
      <p class="hint">Só a lista «n.º · primeiro nome e inicial» vai para o telemóvel dos alunos, cifrada. A app confirma o código pessoal de cada resposta; ninguém vê as respostas dos colegas.</p></form>`;
    d.querySelector('#aa-x').onclick=fim;d.querySelector('#aa-c').onclick=fim;
    d.querySelector('#aa-fol').onclick=async()=>{try{const novo=!t.autoavCod;aaTurmaCod(t);await aaFolha(t,false);if(novo)formulario()}catch(e){toast(aaErro(e),'erro')}};
    const fn=d.querySelector('#aa-foln');if(fn)fn.onclick=()=>aaFolha(t,true).catch(e=>toast(aaErro(e),'erro'));
    const rg=d.querySelector('#aa-reg');if(rg)rg.onclick=async()=>{if(!confirm('Gerar códigos novos para esta turma?\n\nOs papéis que os alunos já têm deixam de funcionar e é preciso imprimir papéis novos.'))return;
      for(const s0 of [...aaSess(t)]){try{await aaFechar(t,s0)}catch(_){}}delete t.autoavCod;t.autoavCh={};t.autoavImp=[];aaTurmaCod(t);save();try{audit('Avaliação','Códigos da autoavaliação renovados',t.nome)}catch(_){}toast('Códigos novos criados. Imprima os papéis novos.','ok');formulario()};
    d.querySelector('#aa-ok').onclick=async()=>{const b=d.querySelector('#aa-ok');b.disabled=true;b.innerHTML=ic('refresh',15)+' A abrir…';
      const q={dom:d.querySelector('#aa-qd').checked,nota:d.querySelector('#aa-qn').checked,forte:d.querySelector('#aa-qr').checked,melhorar:d.querySelector('#aa-qr').checked,plano:d.querySelector('#aa-qp').checked,sug:d.querySelector('#aa-qs').checked};
      const md=(d.querySelector('input[name=aa-modo]:checked')||{}).value||'pes';t.autoavModo=md==='geral'?'geral':'pes';save();
      try{await aaQrLib();const s=await aaAbrir(t,+d.querySelector('#aa-p').value,q,+d.querySelector('#aa-m').value,md!=='geral');aberta(s)}catch(e){formulario(aaErro(e))}}};
  const aberta=s=>{const url=aaUrl(s.code);
    d.innerHTML=`<div class="aaw aaon"><header class="aah"><h2 id="aa-t">${ic('users',18)} ${esc(t.nome)} · ${esc(perNome(s.p))} · <span class="aaab">aberta</span></h2><button type="button" class="btn ico" id="aa-x" aria-label="Fechar a janela (a autoavaliação continua aberta)">${ic('x',16)}</button></header>
      <div class="aaqr"><div class="aaqi">${aaQR(url)}</div><div class="aaqt">${s.pes?`<p class="aadica"><b>Os alunos apontam a câmara ao seu papel.</b></p><p class="mut">Quem não tiver o papel aponta a este código (ou abre <b>${esc(url.replace(/#.*$/,'').replace(/^https?:\/\//,''))}</b> e escreve o código da turma), escolhe o número e escreve o seu código pessoal.</p>`:`<p class="aadica"><b>Os alunos apontam a câmara a este código.</b></p><p class="mut">Ou abrem <b>${esc(url.replace(/#.*$/,'').replace(/^https?:\/\//,''))}</b> e escrevem o código da turma. Depois escolhem o seu número — <b>sem código pessoal</b>. Quem tiver o papel também pode usá-lo.</p>`}<p class="aamodo"><span class="tag ${s.pes?'':'ok'}">${s.pes?'Com código pessoal':'Só com o código da turma'}</span> <button type="button" class="btn sm" id="aa-modo">${s.pes?'Deixar responder sem código pessoal':'Voltar a exigir o código pessoal'}</button></p><p class="aacod" aria-label="Código da turma ${esc(s.code.split('').join(' '))}">${esc(aaFmt(s.code))}</p>
        <p class="aaest"><b id="aa-n">0</b> de ${ativos.length} responderam · <span id="aa-exp"></span></p></div></div>
      <div class="aavis" id="aa-vis"></div><div id="aa-av"></div>
      ${s.q&&s.q.sug===false?'':`<details class="aabox" id="aa-sugd"><summary><b>${ic('chat',15)} Sugestões para as aulas</b> <span class="mut" id="aa-sugn"></span></summary><div id="aa-sug"></div></details>`}
      <div class="row aaa"><button type="button" class="btn" id="aa-fs">${ic('grid',15)} Ecrã Inteiro</button><button type="button" class="btn" id="aa-cp">${ic('copy',15)} Copiar Link</button><button type="button" class="btn" id="aa-mais">+30 min</button><span class="sp1"></span><button type="button" class="btn dng" id="aa-fim">${ic('check',15)} Fechar e Guardar</button></div></div>`;
    const atual=()=>{const n=s.vistos||[];d.querySelector('#aa-n').textContent=n.length;const r=Math.max(0,s.expira-Date.now());
      d.querySelector('#aa-exp').textContent=r<=0?'fechada':r<3600e3?'fecha dentro de '+Math.ceil(r/60000)+' min':'fecha '+new Date(s.expira).toLocaleString('pt-PT',{weekday:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
      d.querySelector('#aa-vis').innerHTML=ativos.map(a=>`<span class="${n.includes(a.id)?'ok':''}" title="${esc(a.nome)}">${esc(a.num||'')}</span>`).join('');
      /* avisos: códigos errados e alunos que responderam mais de uma vez (o professor escolhe a versão) */
      const V=_aaVers.get(s.code)||{};const nm=aid=>{const a=t.alunos.find(z=>z.id===aid);return a?'N.º '+(a.num||'')+' · '+aaCurto(a.nome):'?'};let h='';
      if((s.rej||[]).length){const g={};s.rej.forEach(x=>{g[x.n]=(g[x.n]||0)+1});h+=`<div class="alert aarej">${ic('alert',15)} <span><b>${s.rej.length} resposta${s.rej.length>1?'s':''} recusada${s.rej.length>1?'s':''}</b> — código pessoal errado (alguém tentou responder por outro aluno?): ${Object.entries(g).map(([n,c])=>'n.º '+esc(n)+(c>1?' ('+c+'×)':'')).join(', ')}. Não foram guardadas.</span></div>`}
      (s.dup||[]).forEach(aid=>{const L=(V[aid]||[]).slice().sort((a,b)=>a.q-b.q);if(L.length<2)return;const usa=(s.esc||{})[aid]||L[L.length-1].q;
        h+=`<div class="aadup"><b>${esc(nm(aid))}</b> respondeu ${L.length} vezes — escolha a que fica: ${L.map(o=>`<button type="button" class="btn sm ${o.q===usa?'pri':''}" data-aadup="${esc(aid)}" data-q="${+o.q||0}">${new Date(o.q).toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'})}${o.nota?' · nota '+esc(o.nota):''}${o.q===usa?' ✓':''}</button>`).join(' ')}</div>`});
      const av=d.querySelector('#aa-av');av.innerHTML=h;av.querySelectorAll('[data-aadup]').forEach(b=>b.onclick=async()=>{s.esc=s.esc||{};s.esc[b.dataset.aadup]=+b.dataset.q;save();try{await aaImportar(t,s)}catch(_){}atual();toast('Ficou a resposta das '+b.textContent.replace(' ✓','').split(' · ')[0],'ok')});
      const sg=d.querySelector('#aa-sug');if(sg){sg.innerHTML=aaSugHtml(t,s.p);const n2=(t.autoavSug||[]).filter(x=>x.p===s.p).length;d.querySelector('#aa-sugn').textContent='('+n2+')'}};
    const puxar=async()=>{try{const k=await aaImportar(t,s);atual();if(k)toast(k===1?'Chegou 1 autoavaliação':'Chegaram '+k+' autoavaliações','ok')}catch(e){console.warn(e)}if(Date.now()>s.expira){clearInterval(tm);atual()}};
    atual();clearInterval(tm);tm=setInterval(puxar,4000);puxar();
    d.querySelector('#aa-x').onclick=fim;
    d.querySelector('#aa-fs').onclick=()=>{d.classList.toggle('aafs');const w=d.querySelector('.aaw');try{if(!document.fullscreenElement&&w.requestFullscreen)w.requestFullscreen();else if(document.fullscreenElement)document.exitFullscreen()}catch(_){}};
    d.querySelector('#aa-cp').onclick=async()=>{try{await navigator.clipboard.writeText(url+'\nCódigo da turma: '+aaFmt(s.code));toast(s.pes?'Link copiado (cada aluno precisa também do seu código pessoal)':'Link copiado (os alunos só precisam de escolher o número)','ok')}catch(_){prompt('Copie:',url)}};
    {const bm=d.querySelector('#aa-modo');if(bm)bm.onclick=async()=>{const novo=!s.pes;if(!novo&&!confirm('Deixar os alunos responderem só com o código da turma?\n\nCada aluno escolhe o seu número sem código pessoal: confia que escolhe o certo.'))return;
      bm.disabled=true;bm.textContent='A mudar…';try{if(tm){clearInterval(tm);tm=0}const min=Math.max(5,Math.ceil((s.expira-Date.now())/60000));t.autoavModo=novo?'pes':'geral';const s2=await aaAbrir(t,s.p,s.q,min,novo);toast(novo?'Volta a ser preciso o código pessoal':'Agora basta o código da turma','ok');aberta(s2)}catch(e){bm.disabled=false;toast(aaErro(e),'erro')}}}
    d.querySelector('#aa-mais').onclick=async()=>{try{await aaMais(t,s,30);atual();if(!tm)tm=setInterval(puxar,4000);toast('Mais 30 minutos','ok')}catch(e){toast(aaErro(e),'erro')}};
    d.querySelector('#aa-fim').onclick=async()=>{const b=d.querySelector('#aa-fim');b.disabled=true;try{await aaFechar(t,s);toast('Autoavaliação fechada: '+(s.n||0)+' resposta(s) guardada(s) no Perfil de Aprendizagem. Os papéis continuam a servir na próxima.','ok');fim()}catch(e){b.disabled=false;toast(aaErro(e),'erro')}}};
  const ab=aaSess(t).find(s=>Date.now()<s.expira);try{d.showModal()}catch(_){d.setAttribute('open','')}
  if(ab){try{await aaQrLib();aberta(ab)}catch(e){formulario(aaErro(e))}}else formulario()}

/* botões: barra da turma e Perfil de Aprendizagem */
{const _g=go;go=function(v){const r=_g.apply(this,arguments);try{if(aaLigado()&&window.__esPronto&&['alunos'].includes(VIEW)&&T()){const bx=$('#barx');if(bx&&!bx.querySelector('#b-aatlm')){const b=document.createElement('button');b.className='btn';b.id='b-aatlm';const ab=aaSess(T()).some(s=>Date.now()<s.expira);b.innerHTML=ic('users',15)+(ab?' Autoavaliação (aberta)':' Autoavaliação pelo Telemóvel');if(ab)b.classList.add('pri');b.onclick=aaPainel;bx.appendChild(b)}}}catch(e){console.warn(e)}return r}}
{const _pA=perfilAluno;perfilAluno=function(){const r=_pA.apply(this,arguments);try{const liga=()=>{const h=document.querySelector('#perfilap .pauto h2');if(h&&aaLigado()&&!h.querySelector('.aapb')){h.insertAdjacentHTML('beforeend',` <button type="button" class="btn sm aapb">${ic('users',13)} Pedir pelo Telemóvel</button>`);h.querySelector('.aapb').onclick=()=>{const o=$('#perfilap');if(o)o.remove();document.body.classList.remove('perfil-on');aaPainel()}}
    const o=$('#perfilap');if(o&&!o.dataset.aamo){o.dataset.aamo=1;new MutationObserver(liga).observe(o,{childList:true,subtree:true})}};liga()}catch(e){console.warn(e)}return r}}
/* Definições › Segurança: ligar/desligar */
