/* correspondência pergunta → item do instrumento (ou domínio de cada pergunta, num instrumento novo) */
function fmItensDlg(f,as){const t=fmTurma(as.tid),i=fmInst(as);if(!t||!i)return;const Q=fmQPts(f);
  const corpo=as.nova?`<p class="hint" style="margin-top:0">O instrumento «${esc(i.nome)}» tem um item por pergunta. Escolha o domínio de cada pergunta.</p><div class="fmdoms">${Q.map((q,k)=>`<label class="fmlin"><span>P${k+1} · ${esc((q.titulo||'').slice(0,60))} <small class="mut">(${nf(q.pts)} pts)</small></span><select data-fidom="${q.id}">${t.dominios.map(d=>`<option value="${d.id}" ${((as.dom||{})[q.id]||(i.itens.find(x=>x.fmq===q.id)||{}).dom)===d.id?'selected':''}>${esc(d.ab||d.nome)}</option>`).join('')}</select></label>`).join('')}</div>`
    :`<p class="hint" style="margin-top:0">Para cada pergunta do teste, escolha o item de «${esc(i.nome)}» onde os pontos entram. Várias perguntas podem ir para o mesmo item: os pontos somam-se e convertem-se na cotação do item.</p>
      <div class="row" style="gap:6px;margin-bottom:8px"><button class="btn sm" id="fi-sug">${ic('sparkle',13)} Sugerir</button><span class="mut" id="fi-res"></span></div>
      <div class="fmdoms">${Q.map((q,k)=>`<label class="fmlin"><span>P${k+1} · ${esc((q.titulo||'').slice(0,60))} <small class="mut">(${nf(q.pts)} pts)</small></span><select data-fimap="${q.id}"><option value="">— não conta —</option>${i.itens.map(it=>`<option value="${it.id}" ${(as.map||{})[q.id]===it.id?'selected':''}>${esc(it.rot)} · ${esc((t.dominios.find(d=>d.id===it.dom)||{}).ab||'')} · ${nf(it.cot)} pts</option>`).join('')}</select></label>`).join('')}</div>`;
  openDrawer('Itens · '+i.nome+' · '+t.nome,`<div class="ed">${corpo}<div class="row" style="margin-top:12px"><span class="sp1"></span><button class="btn pri" id="fi-ok">${ic('check',14)} Guardar e Lançar</button></div></div>`);
  const resumo=()=>{const r=$('#fi-res');if(!r)return;const m={};$$('[data-fimap]').forEach(s=>{if(s.value)(m[s.value]=m[s.value]||0,m[s.value]+=1)});const sem=i.itens.filter(it=>!m[it.id]).length;r.textContent=sem?sem+' item(ns) do instrumento sem pergunta':'Todos os itens têm perguntas'};
  $$('[data-fimap]').forEach(s=>s.onchange=resumo);resumo();const sg=$('#fi-sug');if(sg)sg.onclick=()=>{const m=fmSugerir(f,i);$$('[data-fimap]').forEach(s=>s.value=m[s.dataset.fimap]||'');resumo()};
  $('#fi-ok').onclick=()=>{if(as.nova){as.dom=as.dom||{};$$('[data-fidom]').forEach(s=>as.dom[s.dataset.fidom]=s.value)}else{as.map={};$$('[data-fimap]').forEach(s=>{if(s.value)as.map[s.dataset.fimap]=s.value})}
    const n=fmSincronizar(f);save();closeDrawer();toast(n?n+' aluno(s) com classificação em «'+i.nome+'» · '+t.nome:'Ligado a «'+i.nome+'». As classificações entram quando chegarem respostas.','ok');if(VIEW==='forms'&&UI.fmId===f.id)fmEditor(f)}}
/* compatibilidade: o antigo «Enviar para a Avaliação» abre agora a associação */
function fmAvaliacaoDlg(f){const L=fmAssoc(f).filter(a=>a.inst);if(L.length){const n=fmSincronizar(f);toast(n?n+' classificação(ões) lançada(s) em '+L.length+' instrumento(s)':'Sem respostas para lançar','ok')}fmAssocDlg(f,fmTurma((f.resp.find(r=>r.tid)||{}).tid))}
/* nas turmas: os instrumentos ligados mostram o teste do Spruce Forms e podem ligar-se a um */
const fmDoInst=(t,i)=>FMS().filter(f=>fmAssoc(f).some(a=>a.tid===t.id&&a.inst===i.id));
{const _vIs=vInstrumentos;vInstrumentos=function(){const r=_vIs.apply(this,arguments);try{if(!fmOn())return r;const t=T();if(!t)return r;
  $$('#view [data-irow]').forEach(tr=>{const i=t.instrumentos.find(x=>x.id===tr.dataset.irow);const F=i?fmDoInst(t,i):[];if(!F.length)return;const c=tr.querySelector('td');c.insertAdjacentHTML('beforeend',F.map(f=>` <button class="fmchip" data-fmab="${f.id}" title="Abrir no Spruce Forms">${ic('clipboard',12)} ${esc(f.titulo.slice(0,28))}</button>`).join(''))});
  $$('#view [data-fmab]').forEach(b=>b.onclick=e=>{e.stopPropagation();UI.fmId=b.dataset.fmab;UI.fmTab='resp';go('forms')})}catch(e){console.warn(e)}return r};if(go._f)go._f.instrumentos=vInstrumentos}
{const _vI=vInstrumento;vInstrumento=function(id){const r=_vI.apply(this,arguments);try{if(!fmOn())return r;const t=T();const i=t&&t.instrumentos.find(x=>x.id===id);if(!i)return r;const F=fmDoInst(t,i);const tabs=document.querySelector('#view .tabs');if(!tabs)return r;
  tabs.insertAdjacentHTML('beforebegin',`<div class="fmibar noprint">${ic('clipboard',15)} ${F.length?F.map(f=>`<span>${f.quiz?'Teste':'Formulário'} do Spruce Forms: <b>${esc(f.titulo)}</b> · ${f.resp.filter(x=>x.tid===t.id).length} resposta(s)</span> <button class="btn sm" data-fmab="${f.id}">Abrir</button>${f.quiz?` <button class="btn sm" data-fmsy="${f.id}">${ic('refresh',13)} Lançar agora</button>`:''}`).join(' · '):'<span class="mut">Este instrumento não está ligado a nenhum teste do Spruce Forms.</span>'} <button class="btn sm" id="fm-ligar">${ic('plus',13)} Ligar teste do Spruce Forms</button></div>`);
  $$('#view [data-fmab]').forEach(b=>b.onclick=()=>{UI.fmId=b.dataset.fmab;UI.fmTab='resp';go('forms')});
  $$('#view [data-fmsy]').forEach(b=>b.onclick=()=>{const f=FMS().find(x=>x.id===b.dataset.fmsy);const n=fmSincronizar(f);toast(n+' aluno(s) atualizado(s)','ok');vInstrumento(id)});
  $('#fm-ligar').onclick=()=>fmLigarAoInst(t,i)}catch(e){console.warn(e)}return r}}
function fmLigarAoInst(t,i){const L=FMS();if(!L.length)return toast('Ainda não há formulários no Spruce Forms.','erro');
  openDrawer('Ligar teste do Spruce Forms · '+i.nome,`<div class="ed"><p class="hint" style="margin-top:0">Escolha o teste ou formulário a ligar a «${esc(i.nome)}» (${esc(t.nome)}).</p><div class="fmasl">${L.map(f=>`<button class="fmas fmasb" data-fmlg="${f.id}"><div><b>${esc(f.titulo)}</b><br><span class="mut">${f.quiz?'Teste · '+nf(fmPts(f))+' pts':'Formulário'} · ${fmPerg(f).length} perguntas · ${f.resp.length} respostas</span></div>${ic('plus',16)}</button>`).join('')}</div>
    <button class="btn" id="fm-lgn" style="margin-top:10px">${ic('plus',14)} Criar um teste novo para este instrumento</button></div>`);
  const liga=f=>{const L2=fmAssoc(f);if(L2.some(a=>a.tid===t.id&&a.inst===i.id)){closeDrawer();return toast('Já está ligado.','ok')}const as={id:uid(),tid:t.id,inst:i.id,nova:false,map:f.quiz?fmSugerir(f,i):{},auto:true};L2.push(as);save();if(f.quiz){fmSincronizar(f);fmItensDlg(f,as)}else{closeDrawer();vInstrumento(i.id)}};
  $$('[data-fmlg]').forEach(b=>b.onclick=()=>liga(FMS().find(x=>x.id===b.dataset.fmlg)));
  $('#fm-lgn').onclick=()=>{const f=fmNovo(true);f.titulo=i.nome;f.itens=i.itens.map(it=>Object.assign(fmQ('escolha'),{titulo:it.rot,pts:+it.cot||1}));const as={id:uid(),tid:t.id,inst:i.id,nova:false,map:{},auto:true};f.itens.forEach((q,k)=>as.map[q.id]=i.itens[k].id);fmAssoc(f).push(as);save();closeDrawer();UI.fmId=f.id;UI.fmTab='perg';UI.fmSel=f.itens[0]&&f.itens[0].id;go('forms');toast('Teste criado com uma pergunta por item de «'+i.nome+'». Escreva as perguntas.','ok')}}
/* ---------- definições: ligar/desligar ---------- */
{const _vDf=vDefinicoes;vDefinicoes=function(){const r=_vDf.apply(this,arguments);try{const c=document.querySelector('#view #aa-def')||document.querySelector('#view #ar-def');if(c&&!document.querySelector('#fm-def')){c.insertAdjacentHTML('afterend',`<label class="chk" style="margin-top:8px" id="fm-def"><input type="checkbox" id="fm-on" ${fmOn()?'checked':''}> ${ic('clipboard',15)} <span><b>Spruce Forms</b><br><span class="mut">Inquéritos e testes online; os alunos respondem por QR code ou código e os testes entram na avaliação.</span></span></label>`);
  $('#fm-on').onchange=e=>{S.cfg.formsOn=e.target.checked;save();try{$$('#side [data-v="forms"]').forEach(b=>b.hidden=!fmOn())}catch(_){}toast(e.target.checked?'Spruce Forms ligados':'Spruce Forms desligados','ok')}}}catch(e){console.warn(e)}return r};if(go._f)go._f.definicoes=vDefinicoes}
try{AJUDA.push({id:'forms',ic:'clipboard',t:'Spruce Forms — Formulários e Testes Online',gif:null,txt:`<p>Crie <b>formulários</b> (inquéritos, fichas, autoavaliações) e <b>testes</b> com pontos e correção automática.</p><p>Para <b>testes e fichas de avaliação digitais</b> (Verdadeiro/Falso, Preencher o texto, Conectar, Tabela, Legendar, Segmentos, rubricas, modo exame e agendamento) use o módulo <b>Spruce Exam</b>, que é independente do Spruce Forms. Os formulários antigos com esses tipos continuam a funcionar. Em <b>Resumo</b> vê a <b>taxa de acerto</b> de cada pergunta.</p>
<ul><li><b>Tipos de pergunta</b>: escolha (uma ou várias, «Outra», baralhar, lista pendente), texto (curto, longo, só números), classificação (estrelas ou números), data, ordenação, Likert, Net Promoter Score, secções (com saltos conforme a resposta) e texto/imagem. Cada pergunta pode ter imagem e ser obrigatória.</li>
<li><b>Testes</b>: pontos por pergunta, respostas certas, comentário por opção; escolha, texto curto e ordenação corrigem-se sozinhos; as respostas longas corrigem-se à mão em Respostas.</li>
<li><b>Definições</b>: só alunos da turma com código pessoal (ou escolher o número), uma resposta por aluno, datas de início e fim, baralhar perguntas, tempo limite, mostrar resultados logo / quando publicar / nunca, mensagem de agradecimento. <b>Tema</b> com cor.</li>
<li><b>Recolher Respostas</b>: escolha a turma e quanto tempo; aparece o <b>QR code e o código</b> (pode projetar). Os alunos abrem <b>eduspruce.pt/forms</b>, escrevem o código, escolhem o número (e o código pessoal) e respondem. Tudo vai cifrado.</li>
<li><b>Turmas e momentos de avaliação</b> (botão <b>Turmas</b>): ligue o teste ou formulário a uma ou mais turmas e, em cada uma, a um <b>momento de avaliação</b> já marcado (Momento de Avaliação, teste, ficha…) ou a um instrumento novo criado a partir das perguntas. Num instrumento existente, escolha o item de cada pergunta (várias perguntas podem somar no mesmo item; os pontos convertem-se na cotação do item). As classificações entram sozinhas na grelha à medida que chegam respostas e correções. A recolha de respostas sugere logo a turma ligada.</li>
<li>No instrumento da turma aparece o teste ligado (Abrir · Lançar agora) e o botão <b>Ligar teste do Spruce Forms</b>, que também cria um teste novo com uma pergunta por item.</li>
<li><b>Respostas</b>: resumo com gráficos por pergunta, respostas individuais (correção e comentários), classificações, exportação para Excel (CSV) e <b>Publicar Classificações</b> (os alunos veem as respostas certas e os comentários).</li></ul>`})}catch(_){}
