/* correspondência pergunta → item do instrumento (ou domínio de cada pergunta, num instrumento novo) */
function pvItensDlg(f,as){const t=pvTurma(as.tid),i=pvInst(as);if(!t||!i)return;const Q=pvQPts(f);
  const corpo=as.nova?`<p class="hint" style="margin-top:0">O instrumento «${esc(i.nome)}» tem um item por pergunta. Escolha o domínio de cada pergunta.</p><div class="pqdoms">${Q.map((q,k)=>`<label class="pqlin nt"><span>P${k+1} · ${esc((q.titulo||'').slice(0,60))} <small class="mut">(${nf(q.pts)} pts)</small></span><select data-pvidom="${q.id}">${t.dominios.map(d=>`<option value="${d.id}" ${((as.dom||{})[q.id]||(i.itens.find(x=>x.pqq===q.id)||{}).dom)===d.id?'selected':''}>${esc(d.ab||d.nome)}</option>`).join('')}</select></label>`).join('')}</div>`
    :`<p class="hint" style="margin-top:0">Para cada pergunta do teste, escolha o item de «${esc(i.nome)}» onde os pontos entram. Várias perguntas podem ir para o mesmo item: os pontos somam-se e convertem-se na cotação do item.</p>
      <div class="row" style="gap:6px;margin-bottom:8px"><button class="btn sm" id="pvi-sug">${ic('sparkle',13)} Sugerir</button><span class="mut" id="pvi-res"></span></div>
      <div class="pqdoms">${Q.map((q,k)=>`<label class="pqlin nt"><span>P${k+1} · ${esc((q.titulo||'').slice(0,60))} <small class="mut">(${nf(q.pts)} pts)</small></span><select data-pvimap="${q.id}"><option value="">— não conta —</option>${i.itens.map(it=>`<option value="${it.id}" ${(as.map||{})[q.id]===it.id?'selected':''}>${esc(it.rot)} · ${esc((t.dominios.find(d=>d.id===it.dom)||{}).ab||'')} · ${nf(it.cot)} pts</option>`).join('')}</select></label>`).join('')}</div>`;
  openDrawer('Itens · '+i.nome+' · '+t.nome,`<div class="ed">${corpo}<div class="row" style="margin-top:12px"><span class="sp1"></span><button class="btn pri" id="pvi-ok">${ic('check',14)} Guardar e Lançar</button></div></div>`);
  const resumo=()=>{const r=$('#pvi-res');if(!r)return;const m={};$$('[data-pvimap]').forEach(s=>{if(s.value)(m[s.value]=m[s.value]||0,m[s.value]+=1)});const sem=i.itens.filter(it=>!m[it.id]).length;r.textContent=sem?sem+' item(ns) do instrumento sem pergunta':'Todos os itens têm perguntas'};
  $$('[data-pvimap]').forEach(s=>s.onchange=resumo);resumo();const sg=$('#pvi-sug');if(sg)sg.onclick=()=>{const m=pvSugerir(f,i);$$('[data-pvimap]').forEach(s=>s.value=m[s.dataset.pvimap]||'');resumo()};
  $('#pvi-ok').onclick=()=>{if(as.nova){as.dom=as.dom||{};$$('[data-pvidom]').forEach(s=>as.dom[s.dataset.pvidom]=s.value)}else{as.map={};$$('[data-pvimap]').forEach(s=>{if(s.value)as.map[s.dataset.pvimap]=s.value})}
    const n=pvSincronizar(f);save();closeDrawer();toast(n?n+' aluno(s) com classificação em «'+i.nome+'» · '+t.nome:'Ligado a «'+i.nome+'». As classificações entram quando chegarem respostas.','ok');if(VIEW==='provas')pvEditor(f)}}
/* compatibilidade: o antigo «Enviar para a Avaliação» abre agora a associação */
function pvAvaliacaoDlg(f){const L=pvAssoc(f).filter(a=>a.inst);if(L.length){const n=pvSincronizar(f);toast(n?n+' classificação(ões) lançada(s) em '+L.length+' instrumento(s)':'Sem respostas para lançar','ok')}pvAssocDlg(f,pvTurma((f.resp.find(r=>r.tid)||{}).tid))}
/* ---------- tipos novos na correção e no que vai para o aluno ---------- */
{const _c=pvCorrigir;pvCorrigir=function(f,q,v){if(!f.quiz||!(+q.pts))return null;const P=+q.pts;let a;
  if(q.tipo==='tabela'){const L=q.lins||[],C=q.cols||[];if(!L.length||!C.length)return null;const m=q.marc||{},x=v||{};const lin=r=>C.every((_,k)=>!!m[r+'|'+k]===!!x[r+'|'+k]);a=q.porLinha===false?(L.every((_,r)=>lin(r))?P:0):Math.round(P*L.filter((_,r)=>lin(r)).length/L.length*100)/100}
  else if(q.tipo==='legendar'){const M=q.marcas||[];if(!M.length)return null;const z=Array.isArray(v)?v:[];a=Math.round(P*M.filter((m,k)=>String(m.t||'').split('|').some(t=>t.trim()&&pvNorm(t)===pvNorm(z[k]))).length/M.length*100)/100}
  else if(q.tipo==='segmentos'){const Z=q.zonas||[];if(!Z.length)return null;const V=Array.isArray(v)?v:[];a=Math.round(P*Z.filter(zz=>V.some(p=>p.x>=zz.x&&p.x<=zz.x+zz.w&&p.y>=zz.y&&p.y<=zz.y+zz.h)).length/Z.length*100)/100}
  else if(q.tipo==='ordem'&&q.parc){if(!Array.isArray(v))return 0;const c=q.ops.map(o=>o.id);a=Math.round(P*c.filter((id,i)=>v[i]===id).length/c.length*100)/100}
  else a=_c.apply(this,arguments);
  if(a!=null&&q.dico&&a<P)a=0;return a}}
{const _p=pvPublico;pvPublico=function(f,comChave){const o=_p.apply(this,arguments);o.itens.forEach((q,k)=>{const src=f.itens[k]||q;
  if(q.tipo==='segmentos')q.n=(src.zonas||[]).length;
  if(!comChave){delete q.resol;if(q.tipo==='tabela')delete q.marc;if(q.tipo==='legendar')q.marcas=(q.marcas||[]).map(m=>({id:m.id,x:m.x,y:m.y}));if(q.tipo==='segmentos')delete q.zonas}
  if(q.tipo==='lacunas'&&src.modo&&src.modo!=='escrever'){q.banco=pvBaralhar([...pvLacunas(src).map(a=>a[0]).filter(Boolean),...(src.extraP||[])]);if(src.ordenarP)q.banco.sort((a,b)=>a.localeCompare(b,'pt'))}
  ['etq','exId','criado','alterado'].forEach(x=>delete q[x])});o.formato=f.defs.formato;return o}}
{const _d=pvDadosSessao;pvDadosSessao=async function(f,t,s){const D=await _d.apply(this,arguments);D.mod='provas';D.quad=pvQuad();return D}}
const pvQuad=()=>{try{return document.body.classList.contains('est-sge')}catch(_){return false}};
const pvEditor=f=>{if(VIEW!=='provas')return;UI.pvEd={k:'av',id:f.id};vProvas()};
/* ---------- utilitários ---------- */
const pvTxt=h=>{const d=document.createElement('div');d.innerHTML=String(h||'');d.querySelectorAll('img').forEach(i=>i.replaceWith(' [imagem] '));d.querySelectorAll('br,p,div,li').forEach(x=>x.append(' '));return d.textContent.replace(/\s+/g,' ').trim()};
function pvLimpa(h){const d=new DOMParser().parseFromString('<div>'+String(h||'')+'</div>','text/html');const OK=['B','STRONG','I','EM','U','SUB','SUP','BR','P','DIV','UL','OL','LI','H3','SPAN','IMG','TABLE','TBODY','TR','TD','TH','S','AUDIO','A'];
  const vai=n=>{[...n.childNodes].forEach(c=>{if(c.nodeType===3)return;if(c.nodeType!==1||!OK.includes(c.tagName)){if(c.nodeType===1&&!['SCRIPT','STYLE','IFRAME','OBJECT','META','LINK'].includes(c.tagName)){vai(c);c.replaceWith(...c.childNodes)}else c.remove();return}
    [...c.attributes].forEach(a=>{const ok=(c.tagName==='IMG'&&a.name==='src'&&/^data:image\/(png|jpe?g|gif|webp);base64,/i.test(a.value))||(c.tagName==='AUDIO'&&((a.name==='src'&&/^data:audio\/[a-z0-9.+-]+(;codecs=[a-z0-9.,]+)?;base64,/i.test(a.value))||a.name==='controls'))||(c.tagName==='A'&&a.name==='href'&&/^https?:\/\//i.test(a.value))||(c.tagName==='SPAN'&&a.name==='class'&&/^(fr|fn|fd|rd)$/.test(a.value));if(!ok)c.removeAttribute(a.name)});
    if(c.tagName==='A'){c.setAttribute('target','_blank');c.setAttribute('rel','noopener')}if(c.tagName==='AUDIO')c.setAttribute('controls','');if((c.tagName==='IMG'||c.tagName==='AUDIO')&&!c.getAttribute('src'))c.remove();else vai(c)})};
  const r=d.body.firstChild;vai(r);return r.innerHTML.trim()}
const pvHa=ts=>{if(!ts)return '';const m=Math.floor((Date.now()-ts)/60000);if(m<1)return 'agora';if(m<60)return 'há '+m+' min';const h=Math.floor(m/60);if(h<24)return 'há '+h+' h';const d=Math.floor(h/24);if(d<31)return 'há '+d+' dia'+(d===1?'':'s');const me=Math.floor(d/30);if(me<12)return 'há '+me+(me===1?' mês':' meses');const a=Math.floor(d/365);return 'há '+a+' ano'+(a===1?'':'s')};
const pvHora=iso=>{const d=new Date(iso);return isNaN(d)?'':String(d.getHours()).padStart(2,'0')+'h'+String(d.getMinutes()).padStart(2,'0')+', '+d.toLocaleDateString('pt-PT',{day:'numeric',month:'short'})};
const pvDT=iso=>{const d=new Date(iso);return isNaN(d)?'':d.toLocaleString('pt-PT',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})};
const pvLocal=d=>{const z=new Date(d);z.setMinutes(z.getMinutes()-z.getTimezoneOffset());return z.toISOString().slice(0,16)};
const pvTurmaNome=tid=>{const t=pvTurma(tid);return t?t.nome+' · '+t.disciplina:'Sem turma'};
const pvSha=async s=>aaHex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))).slice(0,40);
async function pvRpc(fn,args){const sb=await aaSb();if(!sb||!sb.rpc)throw new Error('A base de dados não está disponível.');const {data,error}=await sb.rpc(fn,args||{});if(error)throw new Error(/does not exist|PGRST202|Could not find/i.test(error.message)?'Falta correr no Supabase o ficheiro 0015_provas.sql (partilha do Spruce Exam).':aaErro(error));return data}
const pvClone=o=>JSON.parse(JSON.stringify(o));
function pvImg(file,max){max=max||1000;return new Promise((ok,ko)=>{if(!file||!/^image\//.test(file.type))return ko(new Error('Escolha uma imagem.'));const rd=new FileReader();rd.onerror=()=>ko(new Error('Não foi possível ler a imagem.'));
  rd.onload=()=>{const im=new Image();im.onerror=()=>ko(new Error('Imagem inválida.'));im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height));const cv=document.createElement('canvas');cv.width=Math.round(im.width*k);cv.height=Math.round(im.height*k);const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,cv.width,cv.height);cx.drawImage(im,0,0,cv.width,cv.height);
    const png=file.type==='image/png'&&cv.width*cv.height<250000;ok(cv.toDataURL(png?'image/png':'image/jpeg',.78))};im.src=rd.result};rd.readAsDataURL(file)})}
const pvEscolherImg=()=>new Promise(ok=>{const i=document.createElement('input');i.type='file';i.accept='image/*';i.onchange=()=>ok(i.files[0]||null);i.click()});
function pvTabHtml(q,v){const C=q.cols||[],L=q.lins||[],m=q.marc||{},x=v||{};return `<table class="pvtbv"><tr><th></th>${C.map(c=>`<th>${esc(c)}</th>`).join('')}</tr>${L.map((l,r)=>`<tr><th>${esc(l)}</th>${C.map((c,k)=>{const a=!!x[r+'|'+k],b=!!m[r+'|'+k];return `<td class="${v===m?'':a===b?'ok':'ko'}">${a?'✓':''}</td>`}).join('')}</tr>`).join('')}</table>`}
function pvSegHtml(q,v){const n=x=>+x||0;return `<div class="pvleg">${q.img?`<img src="${esc(q.img)}" alt="">`:''}${(q.zonas||[]).map(z=>`<b class="pvz" style="left:${n(z.x)}%;top:${n(z.y)}%;width:${n(z.w)}%;height:${n(z.h)}%"></b>`).join('')}${(Array.isArray(v)?v:[]).map((p,k)=>`<i style="left:${n(p&&p.x)}%;top:${n(p&&p.y)}%">${k+1}</i>`).join('')}</div>`}
function pvMudou(a){a.alterado=Date.now();save();(a.sess||[]).filter(s=>Date.now()<s.expira).forEach(s=>pvAtualizarSessao(a,s).catch(e=>console.warn(e)))}
const pvEstado=a=>{const n=Date.now();let st='';Object.entries(a.ag||{}).forEach(([c,g])=>{if(!(a.sess||[]).some(s=>s.code===c)&&!g.fechada){g.fechada=1}const i=+new Date(g.ini||0),f=+new Date(g.fim||0);if(i<=n&&n<=f&&!g.fechada)st='at';else if(n<i&&!g.fechada&&st!=='at')st='ag';else if(!st)st='te'});return st};
const PV_EST={'':['Agendar','calendar',''],ag:['Agendado','calcheck','ag'],at:['A decorrer','send','at'],te:['Terminado','checks','te']};
/* ---------- novo exercício ---------- */
function pvExNovo(tipo){const e={id:uid(),tipo,html:'',titulo:'',pts:1,etq:[],dico:false,extra:'',extraA:false,resol:'',just:false,criado:Date.now(),alterado:Date.now()};
  if(tipo==='escolha')Object.assign(e,{ops:[1,2,3,4].map(k=>({id:uid()+k,t:'',certa:false})),baralhar:false});
  if(tipo==='vf')Object.assign(e,{linhas:[{id:uid(),t:'',v:true}]});
  if(tipo==='texto')Object.assign(e,{longo:true,contar:true,mat:false,resp:[],rub:'',num:null});
  if(tipo==='lacunas')Object.assign(e,{texto:'',modo:'arrastar',extraP:[],ordenarP:false});
  if(tipo==='ordem')Object.assign(e,{ops:[1,2,3,4].map(k=>({id:uid()+k,t:''}))});
  if(tipo==='ligar')Object.assign(e,{pares:[1,2,3].map(k=>({id:uid()+k,a:'',b:'',bid:uid()+'b'+k}))});
  if(tipo==='tabela')Object.assign(e,{cols:['',''],lins:['',''],marc:{},porLinha:true});
  if(tipo==='legendar')Object.assign(e,{img:'',marcas:[]});
  if(tipo==='segmentos')Object.assign(e,{img:'',zonas:[]});
  return e}
/* prepara um exercício para entrar numa avaliação (cópia editável, com o formato que a página do aluno entende) */
function pvParaItem(e){const q=pvClone(e);q.exId=e.id;q.id=uid();q.titulo=pvTxt(q.html).slice(0,200)||pvTipo(q.tipo)[2];q.sub='';q.obrig=false;
  if(q.tipo==='escolha'){q.ops=q.ops.filter(o=>String(o.t).trim()!=='');q.multi=q.ops.filter(o=>o.certa).length>1}
  if(q.tipo==='ordem'){q.ops=q.ops.filter(o=>String(o.t).trim()!=='');q.parc=!q.dico}
  if(q.tipo==='ligar')q.pares=q.pares.filter(p=>p.a.trim()||p.b.trim());
  if(q.tipo==='vf')q.linhas=q.linhas.filter((l,i)=>i===0||l.t.trim());
  return q}
function pvAvNova(t){const a={id:uid(),titulo:t||'Avaliação sem título',desc:'',quiz:true,cor:pvAcc(),itens:[],defs:pvDefs(),resp:[],sess:[],assoc:[],ag:{},etq:[],criado:Date.now(),alterado:Date.now(),publicado:false};PV().av.unshift(a);save();return a}
/* ---------- editor de texto com formatação ---------- */
const PV_SIM=['²','³','√','∛','π','≤','≥','≠','≈','±','×','÷','∞','½','¼','°','∈','∉','∪','∩','⊂','∅','→','⇔','α','β','γ','Δ','θ','λ','μ','Σ','€'];
function pvRte(id,html,ph,min){return `<div class="pvrte" data-rte="${id}"><div class="pvrtb" role="toolbar" aria-label="Formatação"><select data-rf aria-label="Estilo"><option value="p">Normal</option><option value="h3">Título</option></select>
  <button type="button" data-rc="bold" title="Negrito"><b>B</b></button><button type="button" data-rc="italic" title="Itálico"><i>I</i></button><button type="button" data-rc="underline" title="Sublinhado"><u>U</u></button><button type="button" data-rc="subscript" title="Índice inferior">x<sub>2</sub></button><button type="button" data-rc="superscript" title="Expoente">x<sup>2</sup></button>
  <span class="pvsep"></span><button type="button" data-rc="insertOrderedList" title="Lista numerada">1.</button><button type="button" data-rc="insertUnorderedList" title="Lista">•</button><button type="button" data-rc="tabela" title="Tabela">${ic('grid',14)}</button>
  <span class="pvsep"></span><button type="button" data-rc="lnk" title="Ligação">${ic('flow',15)}</button><button type="button" data-rc="img" title="Imagem">${ic('image',15)}</button><button type="button" data-rc="aud" title="Gravar áudio (até 60 s)">${ic('mic',15)}</button><button type="button" data-rc="fml" title="Fórmula (fração, raiz, potência)">√x</button><button type="button" data-rc="sim" title="Símbolos matemáticos"><i>f</i>x</button><button type="button" data-rc="removeFormat" title="Limpar formatação">T<sub>×</sub></button>
  <div class="pvsim" hidden>${PV_SIM.map(x=>`<button type="button" data-si="${x}">${x}</button>`).join('')}</div></div>
  <div class="pved" contenteditable="true" data-ph="${esc(ph||'')}" style="min-height:${min||52}px">${pvLimpa(html)}</div></div>`}
function pvRteBind(root){root.querySelectorAll('[data-rte]').forEach(w=>{const ed=w.querySelector('.pved');let rg=null;const guarda=()=>{const s=getSelection();if(s.rangeCount&&ed.contains(s.anchorNode))rg=s.getRangeAt(0).cloneRange()};const repoe=()=>{ed.focus();if(rg){const s=getSelection();s.removeAllRanges();s.addRange(rg)}};
  ed.addEventListener('keyup',guarda);ed.addEventListener('mouseup',guarda);ed.addEventListener('blur',guarda);
  w.querySelectorAll('[data-rc]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=async()=>{const c=b.dataset.rc;
    if(c==='img'){guarda();const f=await pvEscolherImg();if(!f)return;try{const u=await pvImg(f);repoe();document.execCommand('insertImage',false,u)}catch(e){toast(e.message,'erro')}return}
    if(c==='sim'){const p=w.querySelector('.pvsim');p.hidden=!p.hidden;return}
    if(c==='lnk'){guarda();const u=prompt('Endereço (https://…) — ex.: um vídeo do YouTube ou um site');if(!u)return;repoe();document.execCommand('createLink',false,/^https?:\/\//i.test(u)?u:'https://'+u);return}
    if(c==='aud'){guarda();return pvGravarAudio(u=>{repoe();document.execCommand('insertHTML',false,`<audio controls src="${esc(u)}"></audio><p><br></p>`)})}
    if(c==='fml'){guarda();return pvFormulaDlg(h=>{repoe();document.execCommand('insertHTML',false,h+'&nbsp;')})}
    if(c==='tabela'){repoe();document.execCommand('insertHTML',false,'<table><tbody><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><p><br></p>');return}
    repoe();document.execCommand(c,false,null)}});
  w.querySelectorAll('[data-si]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{repoe();document.execCommand('insertText',false,b.dataset.si)}});
  w.querySelector('[data-rf]').onchange=e=>{repoe();document.execCommand('formatBlock',false,e.target.value);e.target.value='p'};
  ed.addEventListener('paste',e=>{const cd=e.clipboardData;if(!cd)return;const it=[...(cd.items||[])].find(i=>i.type&&i.type.startsWith('image/'));if(it){e.preventDefault();pvImg(it.getAsFile()).then(u=>document.execCommand('insertImage',false,u)).catch(x=>toast(x.message,'erro'));return}
    const h=cd.getData('text/html');if(h){e.preventDefault();document.execCommand('insertHTML',false,pvLimpa(h))}})})}
const pvRteVal=(root,id)=>{const ed=root.querySelector(`[data-rte="${id}"] .pved`);return ed?pvLimpa(ed.innerHTML):''};
/* gravar áudio (enunciados de línguas, ditados…): até 60 s, guardado na prova */
async function pvGravarAudio(cb){let st;try{st=await navigator.mediaDevices.getUserMedia({audio:true})}catch(_){return toast('Não foi possível usar o microfone.','erro')}
  const tipo=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>window.MediaRecorder&&MediaRecorder.isTypeSupported(t))||'';const rec=new MediaRecorder(st,tipo?{mimeType:tipo,audioBitsPerSecond:32000}:{});const P=[];let t0=Date.now(),tm;
  rec.ondataavailable=e=>P.push(e.data);rec.onstop=()=>{clearInterval(tm);st.getTracks().forEach(x=>x.stop());const b=new Blob(P,{type:rec.mimeType||'audio/webm'});const r=new FileReader();r.onload=()=>{closeDrawer();cb(String(r.result).replace(/^data:audio\/([a-z0-9]+)[^;]*;/i,'data:audio/$1;'))};r.readAsDataURL(b)};
  openDrawer('Gravar áudio',`<div class="ed" style="text-align:center"><p class="pvrec0">● <b id="ga-t">0:00</b> / 1:00</p><p class="hint">A gravar… fale para o microfone.</p><button class="btn pri" id="ga-ok">${ic('check',14)} Parar e inserir</button> <button class="btn ghost" id="ga-x">Cancelar</button></div>`);
  rec.start();tm=setInterval(()=>{const s=Math.floor((Date.now()-t0)/1000);const e=$('#ga-t');if(e)e.textContent='0:'+String(s).padStart(2,'0');if(s>=60)rec.stop()},250);
  $('#ga-ok').onclick=()=>rec.stop();$('#ga-x').onclick=()=>{rec.onstop=()=>{clearInterval(tm);st.getTracks().forEach(x=>x.stop())};rec.stop();closeDrawer()}}
/* fórmulas simples sem bibliotecas: fração, raiz, potência, índice */
function pvFormulaDlg(cb){openDrawer('Fórmula',`<div class="ed"><div class="seg" style="margin-bottom:10px">${[['fr','Fração'],['rd','Raiz'],['po','Potência'],['in','Índice']].map(([k,l],i)=>`<button type="button" data-fk="${k}" class="${i?'':'on'}">${l}</button>`).join('')}</div>
  <div class="row" style="gap:8px"><div style="flex:1"><label id="fl-a">Numerador</label><input id="fm-a"></div><div style="flex:1" id="fm-bw"><label id="fl-b">Denominador</label><input id="fm-b"></div></div><p>Pré-visualização: <span class="pvenun" id="fm-p"></span></p><button class="btn pri" id="fm-ok">Inserir</button></div>`);
  let k='fr';const h=()=>{const a=esc($('#fm-a').value||'a'),b=esc($('#fm-b').value||'b');return k==='fr'?`<span class="fr"><span class="fn">${a}</span><span class="fd">${b}</span></span>`:k==='rd'?`√<span class="rd">${a}</span>`:k==='po'?`${a}<sup>${b}</sup>`:`${a}<sub>${b}</sub>`};
  const pinta=()=>{$('#fl-a').textContent={fr:'Numerador',rd:'Radicando',po:'Base',in:'Símbolo'}[k];$('#fl-b').textContent={fr:'Denominador',po:'Expoente',in:'Índice'}[k]||'';$('#fm-bw').style.display=k==='rd'?'none':'';$('#fm-p').innerHTML=h()};
  $$('#dw-b [data-fk]').forEach(b=>b.onclick=()=>{k=b.dataset.fk;$$('#dw-b [data-fk]').forEach(x=>x.classList.toggle('on',x===b));pinta()});$('#fm-a').oninput=pinta;$('#fm-b').oninput=pinta;pinta();$('#fm-ok').onclick=()=>{closeDrawer();cb(h())}}
/* importar de Word (.docx) e PDF */
async function pvDocxTexto(buf){const u=new Uint8Array(buf),dv=new DataView(buf);let e=u.length-22;while(e>0&&dv.getUint32(e,true)!==0x06054b50)e--;if(e<=0)throw new Error('O ficheiro não é um Word (.docx).');const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);
  for(let i=0;i<n;i++){const comp=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),fl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),off=dv.getUint32(p+42,true);const nome=new TextDecoder().decode(u.subarray(p+46,p+46+fl));
    if(nome==='word/document.xml'){const ln=dv.getUint16(off+26,true),lx=dv.getUint16(off+28,true);const dados=u.subarray(off+30+ln+lx,off+30+ln+lx+cs);let xml;if(comp===0)xml=new TextDecoder().decode(dados);else xml=await new Response(new Blob([dados]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();
      let q=0,o=0;const ent=x=>x.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
      return xml.split('</w:p>').map(par=>{const nv=par.match(/<w:numPr>[\s\S]*?<w:ilvl w:val="(\d+)"/);let t=ent(par.replace(/<w:tab\/>/g,'\t').replace(/<w:br[^>]*\/>/g,'\n').replace(/<[^>]+>/g,'')).trim();if(!t)return '';
        if(nv){if(+nv[1]===0){q++;o=0;if(!/^\d+\s*[.)]/.test(t))t=q+'. '+t}else{if(!/^[a-h]\s*[).]/i.test(t))t=String.fromCharCode(97+o)+') '+t;o++}}return t}).filter(Boolean).join('\n')}
    p+=46+fl+xl+cl}throw new Error('Não encontrei texto no Word.')}
async function pvPdfTexto(buf){const lib=await getPdfLib();const doc=await lib.getDocument({data:buf}).promise;const L=[];for(let i=1;i<=doc.numPages;i++){const pg=await doc.getPage(i);const tc=await pg.getTextContent();const lin={};tc.items.forEach(it=>{const y=Math.round(it.transform[5]/3);(lin[y]=lin[y]||[]).push(it)});
    Object.keys(lin).map(Number).sort((a,b)=>b-a).forEach(y=>L.push(lin[y].sort((a,b)=>a.transform[4]-b.transform[4]).map(it=>it.str).join(' ').replace(/\s+/g,' ').trim()))}return L.filter(Boolean).join('\n')}
async function pvLerFicheiro(f){const b=await f.arrayBuffer();if(/\.docx$/i.test(f.name))return pvDocxTexto(b);if(/\.pdf$/i.test(f.name)||f.type==='application/pdf')return pvPdfTexto(b);if(/\.(txt|md|csv)$/i.test(f.name))return new TextDecoder().decode(b);throw new Error('Use um ficheiro Word (.docx), PDF ou texto.')}
/* relatórios individuais (versão para imprimir / PDF, com respostas, pontos, comentários e anotações) */
function pvRespTxt(q,v){if(v==null||v===''||(Array.isArray(v)&&!v.length))return '<i>sem resposta</i>';
  if(q.tipo==='escolha')return (Array.isArray(v)?v:[v]).map(x=>esc((q.ops.find(o=>o.id===x)||{}).t||'')).join(', ');if(q.tipo==='ordem')return v.map(x=>esc((q.ops.find(o=>o.id===x)||{}).t||'')).join(' → ');
  if(q.tipo==='vf')return (q.linhas||[]).map(l=>esc(l.t||'Resposta')+': <b>'+(v[l.id]===true?'Verdadeiro':v[l.id]===false?'Falso':'—')+'</b>').join('<br>');
  if(q.tipo==='lacunas'){const P=pvLacPartes(q);return P.map((x,k)=>esc(x)+(k<P.length-1?'<b>['+esc((v||[])[k]||'—')+']</b>':'')).join('')}
  if(q.tipo==='ligar')return (q.pares||[]).map(pp=>esc(pp.a)+' → <b>'+esc(((q.pares||[]).find(z=>z.bid===v[pp.id])||{}).b||'—')+'</b>').join('<br>');
  if(q.tipo==='tabela')return pvTabHtml(q,v);if(q.tipo==='segmentos')return pvSegHtml(q,v);if(q.tipo==='legendar')return (q.marcas||[]).map((m,k)=>(k+1)+': <b>'+esc((v||[])[k]||'—')+'</b>').join('<br>');
  return esc(String(v)).replace(/\n/g,'<br>')}
function pvRelatorios(a,soId){const R_=a.resp.filter(r=>!soId||r.id===soId);if(!R_.length)return toast('Ainda não há submissões.','erro');const w=window.open('','_blank');if(!w)return toast('O navegador bloqueou a janela.','erro');const Q=pvPerg(a);
  const pag=r=>{const P=pvPontuar(a,r);return `<section class="pg"><h1>${esc(a.titulo)}</h1><p class="sub"><b>${esc(r.nome)}</b>${r.num?' · n.º '+esc(r.num):''}${r.tid?' · '+esc(pvTurmaNome(r.tid)):''} · ${new Date(r.t1).toLocaleString('pt-PT')}</p><p class="tot">${nf(P.tot)} / ${nf(P.max)} pontos · ${P.max?Math.round(P.tot/P.max*100):0}% · ${P.max?nf(Math.round(P.tot/P.max*200)/10):0} valores${P.pend?' · '+P.pend+' por corrigir':''}</p>
    ${Q.map((q,k)=>{const rv=(r.rev||{})[q.id]||{};let tx=pvRespTxt(q,r.resp[q.id]);(rv.an||[]).forEach(z=>{const e=esc(z.t);const j=tx.indexOf(e);if(e&&j>=0)tx=tx.slice(0,j)+'<mark>'+e+'</mark><span class="an">'+esc(z.c)+'</span>'+tx.slice(j+e.length)});
      return `<div class="q"><p class="qh"><b>${k+1}.</b> <span class="pt">${P.pq[q.id]==null?'?':nf(P.pq[q.id])} / ${nf(q.pts)}</span></p><div class="en">${pvLimpa(q.html)}</div><div class="rs">${tx}</div>${r.resp[q.id+'~j']?`<div class="rs"><b>Justificação:</b> ${esc(r.resp[q.id+'~j'])}</div>`:''}${rv.c?`<div class="cm"><b>Comentário:</b> ${esc(rv.c)}</div>`:''}${q.resol?`<div class="re"><b>Proposta de resolução:</b> ${esc(q.resol)}</div>`:''}</div>`}).join('')}</section>`};
  w.document.write(`<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><title>Relatórios · ${esc(a.titulo)}</title><style>body{font:12px/1.45 system-ui,sans-serif;color:#111;margin:14mm}h1{font-size:17px;margin:0}.sub{color:#444;margin:2px 0}.tot{font-size:14px;font-weight:700;margin:6px 0 12px;padding:6px 8px;background:#f1f5f9}.pg{page-break-after:always}.pg:last-child{page-break-after:auto}.q{break-inside:avoid;border-top:1px solid #ddd;padding:8px 0}.qh{margin:0}.pt{float:right;font-weight:700}.en img{max-width:100%;max-height:220px}.rs{margin:6px 0;padding:6px 8px;background:#f8fafc;border-left:3px solid #64748b}.cm{color:#7c2d12}.re{color:#14532d}mark{background:#fde68a}.an{display:block;font-size:11px;color:#92400e;border-left:2px solid #f59e0b;padding-left:6px}.fr{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center}.fn{border-bottom:1px solid}.rd{border-top:1px solid}table{border-collapse:collapse}td,th{border:1px solid #bbb;padding:3px 8px}.pvleg{position:relative;display:inline-block}.pvleg img{max-width:280px}.pvleg i{position:absolute;transform:translate(-50%,-50%);background:#111;color:#fff;border-radius:50%;width:18px;height:18px;font:700 10px/18px sans-serif;text-align:center;font-style:normal}.pvz{position:absolute;border:2px solid #16a34a}</style></head><body>${R_.map(pag).join('')}</body></html>`);w.document.close();setTimeout(()=>{try{w.focus();w.print()}catch(_){}},400)}
