TITLES.provas='Spruce Exam';
function pvShell(tab,body){const I=[['inicio','home','Início'],['explorar','search','Explorar'],['av','file','Avaliações'],['ex','pencil','Exercícios'],['rub','grid','Rubricas'],['grupos','users','Grupos']];
  const mini=!!(S.cfg&&S.cfg.pvMini);
  return `<div class="pv${mini?' pvmini':''}"><nav class="pvnav" aria-label="Spruce Exam"><div class="pvbrand"><i>${ic('award',18)}</i><span>Spruce Exam</span><button type="button" class="pvcol" id="pv-col" aria-expanded="${mini?'false':'true'}" title="${mini?'Mostrar o menu':'Encolher o menu'}" aria-label="${mini?'Mostrar o menu':'Encolher o menu'}"><b aria-hidden="true">«</b></button></div>${I.map(([k,i,l])=>`<button type="button" data-pvt="${k}" class="${tab===k?'on':''}" title="${l}">${ic(i,18)} <span>${l}</span></button>`).join('')}<span class="pvsp"></span><button type="button" data-pvt="ajuda" title="Ajuda">${ic('help',18)} <span>Ajuda</span></button></nav><div class="pvmain">${body}</div></div>`}
function pvShellBind(){const cb=$('#pv-col');if(cb)cb.onclick=()=>{S.cfg.pvMini=!S.cfg.pvMini;save();const v=$('#view .pv');if(v)v.classList.toggle('pvmini',!!S.cfg.pvMini);cb.setAttribute('aria-expanded',S.cfg.pvMini?'false':'true');const t=S.cfg.pvMini?'Mostrar o menu':'Encolher o menu';cb.title=t;cb.setAttribute('aria-label',t)};$$('#view [data-pvt]').forEach(b=>b.onclick=()=>{if(b.dataset.pvt==='ajuda'){go('ajuda');setTimeout(()=>{const c=[...document.querySelectorAll('#view .ajidx .chip')].find(x=>/^Spruce Exam/.test(x.textContent.trim()));if(c)c.click()},350);return}UI.pvEd=null;UI.pvTab=b.dataset.pvt;vProvas()})}
function vProvas(){if(!pvOn())return go('inicio');const e=UI.pvEd;
  if(e){if(e.k==='av'){const a=PV().av.find(x=>x.id===e.id);if(a)return pvAvEditor(a)}else if(e.k==='ex'&&e.w)return pvExEditor(e.w,e.ctx||{});else if(e.k==='rub'&&e.w)return pvRubEditor(e.w)}
  UI.pvEd=null;const tab=UI.pvTab||'inicio';barBtns([]);$('#view').innerHTML=pvShell(tab,'<div id="pv-main"></div>');pvShellBind();
  ({inicio:pvInicio,explorar:pvExplorar,av:pvListaAv,ex:pvListaEx,rub:pvListaRub,grupos:pvGrupos}[tab]||pvInicio)($('#pv-main'))}
async function pvExplorar(m){const G=PV().grupos;const F=UI.pvFx=UI.pvFx||{q:'',tipo:''};
  m.innerHTML=pvHd('search','Explorar',`<button class="btn" id="px-cod">${ic('download',15)} Importar por código</button>`)+(G.length?`<div class="pvbar"><input type="search" id="px-q" placeholder="Pesquisar nos conteúdos partilhados…" value="${esc(F.q)}"><select id="px-t"><option value="">Tudo</option><option value="av" ${F.tipo==='av'?'selected':''}>Avaliações</option><option value="ex" ${F.tipo==='ex'?'selected':''}>Exercícios</option><option value="rub" ${F.tipo==='rub'?'selected':''}>Rubricas</option></select></div><div id="px-l"><p class="mut">A carregar…</p></div>`:`<div class="pvempty">${ic('search',40)}<p><b>Explore conteúdos dos seus colegas</b><br><span class="mut">Entre num grupo (departamento ou espaço da escola) para ver aqui as avaliações, exercícios e rubricas partilhados.</span></p><button class="btn pri" id="px-g">${ic('users',15)} Ir para Grupos</button></div>`);
  $('#px-cod').onclick=()=>pvImportarDlg();const gg=$('#px-g');if(gg)return gg.onclick=()=>{UI.pvTab='grupos';vProvas()};
  let L=[];for(const g of G){try{const X=await pvRpc('provas_grupo',{p_grupo:await pvSha('es-pv-grupo:'+g.code)})||[];X.forEach(x=>{x.grupo=g.nome;L.push(x)})}catch(e){const el=$('#px-l');if(el)el.innerHTML=`<div class="alert">${esc(e.message)}</div>`;return}}
  const pinta=()=>{const q=normT(F.q);const X=L.filter(x=>(!F.tipo||x.tipo===F.tipo)&&(!q||normT(x.titulo+' '+(x.autor||'')+' '+x.grupo).includes(q)));const el=$('#px-l');if(!el)return;
    el.innerHTML=X.length?X.map(x=>`<div class="pvrow"><div class="pvt"><b>${esc(x.titulo)}</b><div class="pvmeta"><span>${ic(x.tipo==='av'?'file':x.tipo==='ex'?'pencil':'grid',13)} ${x.tipo==='av'?'Avaliação':x.tipo==='ex'?'Exercício':'Rubrica'}</span><span>${ic('users',13)} ${esc(x.grupo)}</span><span>${ic('user',13)} ${esc(x.autor||'—')}</span><span>${new Date(x.criado).toLocaleDateString('pt-PT')}</span></div></div><button class="btn" data-pxi="${x.codigo}">${ic('download',15)} Copiar para mim</button></div>`).join(''):'<div class="pvempty"><p>Nada encontrado.</p></div>';
    el.querySelectorAll('[data-pxi]').forEach(b=>b.onclick=async()=>{try{const r=await pvRpc('provas_importar',{p_codigo:b.dataset.pxi});pvReceber({tipo:r.tipo,dados:r.dados})}catch(e){toast(e.message,'erro')}})};pinta();
  const qi=$('#px-q');if(qi)qi.oninput=()=>{F.q=qi.value;pinta()};const ts=$('#px-t');if(ts)ts.onchange=()=>{F.tipo=ts.value;pinta()}}
