    if(UI.hubEd||e.target.closest('[data-hbed]')){hubEditar(a);return}
    if(a.turma&&!T()){const st=$('#hb-tur');if(st){st.focus();try{st.showPicker()}catch(_){}}toast('Escolha primeiro a turma','info');return}
