  const grupos=TT.map(t=>({t,n:todos.filter(x=>fmAssoc(x).some(as=>as.tid===t.id)).length}));const mais=UI.fmcMais;
  const vazio=`<div class="fmc-vz">${typeof ilustracao==='function'?'':''}<b>${todos.length&&(F.turma||F.q||T!=='rec')?'Nada aqui com este filtro':'Ainda não há questionários nem formulários'+(typeof bcAnoNome==='function'?' em '+esc(bcAnoNome()):'')}</b><span class="mut">Comece por um modelo acima, crie um novo ou use a importação rápida.</span></div>`;
  v.innerHTML=`<div class="fmc">${S.cfg.fmModOff?'':''}<section class="fmc-topo"><div class="fmc-w"><div class="fmc-bts"><button class="fmc-b" id="fmc-q">${ic('award',16)} Novo questionário</button><button class="fmc-b" id="fmc-f">${ic('clipboard',16)} Novo formulário</button><button class="fmc-b ln" id="fmc-i">${ic('upload',16)} Importação rápida</button>${typeof bcBanco==='function'?`<button class="fmc-b ln" id="fmc-bc">${ic('layers',16)} Banco</button>`:''}<span class="sp1"></span><button class="fmc-oc" id="fmc-oc">${S.cfg.fmModOff?'Mostrar modelos':'Ocultar modelos'} <span style="display:inline-block;transform:rotate(${S.cfg.fmModOff?0:180}deg)">⌄</span></button></div>
    ${S.cfg.fmModOff?'':`<h3>Explorar modelos</h3><div class="fmc-mods">${FMC_MOD.map((m,i)=>`<button class="fmc-m" data-fmmod="${m[0]}" style="--a:${m[3]};--b:${m[4]};--d:${i*.06}s"><span class="fmc-mt">${m[1]}</span>${fmcModArte(m[0])}<small>${m[2]}</small></button>`).join('')}<button class="fmc-m gal" id="fmc-gal" style="--d:.24s"><span class="fmc-galart"><i></i><i></i><i></i></span><b>${typeof bcBanco==='function'?'Galeria do Banco':'Ver exemplo'} →</b></button></div>`}</div></section>
    <section class="fmc-w fmc-lista"><div class="fmc-tabs" role="tablist">${TABS.map(t=>`<button role="tab" aria-selected="${T===t[0]}" data-fmct="${t[0]}">${ic(t[2],15)} ${t[1]}</button>`).join('')}<span class="sp1"></span><input id="fm-q" type="search" placeholder="Filtrar por palavra-chave" value="${esc(F.q||'')}"><button class="fmc-v ${vis==='lista'?'on':''}" data-fmvis="lista" aria-label="Lista" title="Lista">${ic('list',16)}</button><button class="fmc-v ${vis==='grelha'?'on':''}" data-fmvis="grelha" aria-label="Grelha" title="Grelha">${ic('grid',16)}</button></div>
    ${F.turma?`<div class="fmc-filt">Turma: <b>${esc((TT.find(t=>t.id===F.turma)||{}).nome||'')}</b> <button id="fmc-xt" aria-label="Tirar o filtro">✕</button></div>`:''}
    ${L.length?(vis==='lista'?`<div class="fmc-ls">${L.map(linha).join('')}</div>`:`<div class="fmc-gr">${L.map(cart).join('')}</div>`):vazio}
    ${grupos.length?`<h3 class="fmc-gt">As minhas turmas</h3><div class="fmc-gru">${(mais?grupos:grupos.slice(0,6)).map(g=>`<button class="fmc-g ${F.turma===g.t.id?'on':''}" data-fmgt="${g.t.id}"><span style="background:${g.t.cor||['#0e7490','#c2410c','#7c3aed','#be185d','#15803d','#1d4ed8','#a16207','#475569'][grupos.indexOf(g)%8]}">${esc((g.t.nome||'?').replace(/[^0-9A-Za-zÀ-ú]/g,'').slice(0,2).toUpperCase())}</span><b>${esc(g.t.nome)}${g.t.disciplina?' · '+esc(g.t.disciplina):''}</b><small>${g.n} formulário${g.n===1?'':'s'}</small></button>`).join('')}</div>${grupos.length>6?`<button class="fmc-mais" id="fmc-mais">${mais?'Mostrar menos':'Mostrar mais'} ⌄</button>`:''}`:''}</section></div>`;
  const re=()=>vForms();
  $('#fmc-q').onclick=()=>fmcCriar('quiz');$('#fmc-f').onclick=()=>{const f=fmNovo(false);UI.fmId=f.id;UI.fmTab='perg';vForms()};$('#fmc-i').onclick=fmcImportar;
  const bc=$('#fmc-bc');if(bc)bc.onclick=()=>bcBanco('forms');$('#fmc-oc').onclick=()=>{S.cfg.fmModOff=!S.cfg.fmModOff;save();re()};
  v.querySelectorAll('[data-fmmod]').forEach(b=>b.onclick=()=>fmcCriar(b.dataset.fmmod));const g=$('#fmc-gal');if(g)g.onclick=()=>typeof bcBanco==='function'?bcBanco('forms'):bvAbrir('forms');
  v.querySelectorAll('[data-fmct]').forEach(b=>b.onclick=()=>{UI.fmcTab=b.dataset.fmct;re()});
  v.querySelectorAll('[data-fmvis]').forEach(b=>b.onclick=()=>{S.cfg.fmVis=b.dataset.fmvis;save();re()});
  v.querySelectorAll('[data-fmgt]').forEach(b=>b.onclick=()=>{F.turma=F.turma===b.dataset.fmgt?'':b.dataset.fmgt;re()});const xt=$('#fmc-xt');if(xt)xt.onclick=()=>{F.turma='';re()};
  const mm=$('#fmc-mais');if(mm)mm.onclick=()=>{UI.fmcMais=!UI.fmcMais;re()};
  v.querySelectorAll('[data-fmfav]').forEach(b=>b.onclick=e=>{e.stopPropagation();const o=FMS().find(x=>x.id===b.dataset.fmfav);if(o){o.fav=!o.fav;save();re()}});
  v.querySelectorAll('[data-fmrc]').forEach(b=>b.onclick=e=>{e.stopPropagation();const o=FMS().find(x=>x.id===b.dataset.fmrc);UI.fmId=o.id;UI.fmTab='perg';vForms();fmRecolherDlg(o)});
  v.querySelectorAll('[data-fmm]').forEach(b=>b.onclick=e=>{e.stopPropagation();fmMaisDlg(FMS().find(x=>x.id===b.dataset.fmm))});
