['pointerdown','keydown','drop','paste'].forEach(ev=>addEventListener(ev,()=>{_anoToque=Date.now();if(_anoLimpo){_anoLimpo=false;try{if((S.anos||[]).some(a=>a&&a.fechado))anoProteger(true)}catch(_){}}},true));
