const AZ_='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
function ufSiglas(h){return ((h&&h.legenda)||[]).filter(l=>/^ufcd$|curta dura/i.test(normT(l.ab))||/curta dura/i.test(normT(l.nome))).map(l=>l.ab)}
