BVM.pulso={nome:'Spruce Live',ic:'chart',tit:'Veja em direto o que a turma já aprendeu.',sub:'Perguntas rápidas com correção automática e uma grelha que se preenche à medida que os alunos respondem — para intervir no momento certo.',
  pe:'Lance uma sala, os alunos entram com o código e as respostas aparecem em direto · sempre formativo, só conta se o professor quiser.',
  maq:()=>{const Q=[['A','B'],['Clorofila','Folhas','Cloroplasto','Pigmento'],['B','A'],['V','F'],['53','170']];
   const AL=[['Afonso Lima',[1,1,1,1,1]],['Beatriz Sousa',[0,0,1,0,null]],['Carlos Pires',[1,0,0,1,1]],['Diana Rocha',[0,0,1,0,0]],['Eva Martins',[0,1,1,0,null]],['Filipe Costa',[0,null,1,0,null]]];
   const cel=(q,ok,r)=>ok===null?'<td class="vz"></td>':`<td class="${ok?'ok':'no'}"><span>${ok?'✓':'✗'} ${ok?Q[q][0]:Q[q][1+((q+r)%(Q[q].length-1))]}</span></td>`;
   const pct=r=>Math.round(r.filter(x=>x===1).length/5*100);
   const tot=q=>Math.round(AL.filter(a=>a[1][q]===1).length/AL.length*100);
   let d=.5;return`<div class="bv-pu2"><div class="bv-puc"><div class="bv-puh"><b>Quiz de Ciências Naturais <i>i</i></b><span class="bv-sp"></span><span class="bv-pub l"><em>❚❚</em> Pausar</span><span class="bv-pub l">${ic('check',14)} Terminar</span><span class="bv-pub">${ic('users',14)} Convidar alunos</span></div>
   <div class="bv-putg">${['Mostrar nomes','Mostrar respostas','Mostrar resultados'].map((t,i)=>`<span style="--d:${.2+i*.1}s"><i></i>${t}</span>`).join('')}</div>
   <table class="bv-put"><thead><tr><th class="n">NOME ↓</th><th class="s">PONTOS ⌄</th>${[1,2,3,4,5].map((n,i)=>`<th style="--c:${['#f5b942','#f2683c','#f5b942','#4f5fa8','#f2683c'][i]}">${n}</th>`).join('')}</tr></thead>
   <tbody>${AL.map((a,r)=>`<tr style="--d:${.3+r*.08}s"><td class="n"><i></i>${a[0]}</td><td class="s">${pct(a[1])}%</td>${a[1].map((ok,q)=>{const c=cel(q,ok,r);d+=.09;return c.replace('<td ',`<td style="--e:${(1+q*.55+r*.12).toFixed(2)}s" `)}).join('')}</tr>`).join('')}
   <tr class="tot"><td class="n">${AL.length} &nbsp;Total da turma</td><td class="s"></td>${[0,1,2,3,4].map(q=>`<td style="--e:${(4.4+q*.1).toFixed(2)}s"><span>${tot(q)}%</span></td>`).join('')}</tr></tbody></table></div>
   <div class="bv-puexp" style="--d:3.2s"><b>${ic('check',14)} Correto!</b><small>Pergunta</small><p>A clorofila dá a cor verde às plantas.</p><small>Explicação</small><p>A clorofila absorve a luz para a fotossíntese.</p></div></div>`}};
function bvAbrir(k){const d=BVM[k];if(!d||$('#mqdemo'))return;
  const o=document.createElement('div');o.id='mqdemo';o.className='bv bv-'+k;o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label',d.nome+' — exemplo');
  o.innerHTML=`<div class="mqd-pn"><button type="button" class="mqd-x" aria-label="Fechar">✕</button>
    <div class="mqd-hero"><div class="mqd-marca">${ic(d.ic,18)} ${d.nome}</div><h2>${d.tit}</h2><p>${d.sub}</p><div class="mqd-bts"><button type="button" class="mqd-go">Começar</button></div></div>
    <div class="mqd-palco"><div class="mqd-mold"><div class="mqd-esc">${d.maq()}</div></div></div><div class="mqd-pe">${d.pe} · volte a ver este exemplo no botão <b>Ver exemplo</b>.</div></div>`;
  document.body.appendChild(o);const esc=o.querySelector('.mqd-esc'),pal=o.querySelector('.mqd-palco');
  const aj=()=>{const s=Math.min(1,(pal.clientWidth-24)/1100,(pal.clientHeight-24)/640);esc.style.transform=`scale(${s})`;esc.parentElement.style.width=(1100*s)+'px';esc.parentElement.style.height=(640*s)+'px'};
  aj();const ro=window.ResizeObserver?new ResizeObserver(aj):null;ro&&ro.observe(pal);
  const fim=()=>{ro&&ro.disconnect();window.removeEventListener('keydown',tec,true);o.classList.add('sai');setTimeout(()=>o.remove(),220);try{S.cfg.bvVisto=S.cfg.bvVisto||{};if(!S.cfg.bvVisto[k]){S.cfg.bvVisto[k]=true;save()}}catch(_){}};
  const tec=e=>{if(e.key==='Escape'){e.stopImmediatePropagation();e.preventDefault();fim()}};window.addEventListener('keydown',tec,true);
  o.querySelector('.mqd-x').onclick=fim;o.querySelector('.mqd-go').onclick=fim;o.onclick=e=>{if(e.target===o)fim()};setTimeout(()=>o.querySelector('.mqd-go').focus(),60)}
/* botão «Ver exemplo» + primeira vez; chamado pelas vistas (moderno/vitrines.js) */
function bvLigar(k){try{const v=$('#view');if(!v)return;let b=$('#bv-ver');if(!b){b=document.createElement('button');b.type='button';b.id='bv-ver';b.className='bv-verb';document.body.appendChild(b)}
  b.dataset.k=k;b.innerHTML=ic('sparkle',15)+'<span>Ver exemplo</span>';b.title='Ver o exemplo de '+BVM[k].nome;b.onclick=()=>bvAbrir(k);
  setTimeout(()=>{try{if(!(S.cfg.bvVisto&&S.cfg.bvVisto[k])&&$('#bv-ver')&&$('#bv-ver').dataset.k===k)bvAbrir(k)}catch(_){}},700)}catch(_){}}
function bvDesligar(){const b=$('#bv-ver');b&&b.remove()}
/* ===================== tema-spruce =====================
   Tema «Spruce»: a aparência do eduspruce.app (céu claro, azul-marinho, sol laranja, Bricolage + Figtree) */
if(!ESTILOS_X.some(([k])=>k==='spruce'))ESTILOS_X.push(['spruce','Spruce','sun','Igual ao eduspruce.app: fundo azul-céu, azul-marinho, toque de laranja, títulos em Bricolage e cartões arredondados']);
try{aplicarPrefs()}catch(_){}
/* ===================== 1.150 · novidades num modal: na primeira entrada depois de uma atualização, mostra tudo o que mudou desde a última versão vista ===================== */
function novidadesDesde(v0){
  const nv=v=>parseFloat(String(v||'0').replace(/[^0-9.]/g,''))||0;
  /* as notas de cada versão vêm do mesmo sítio que Definições › Ferramentas › Novidades */
  let html='';const _od=openDrawer;try{openDrawer=(t,h)=>{html=h};novidades()}catch(e){console.warn(e)}finally{openDrawer=_od}
  const t=document.createElement('div');t.innerHTML=html;
  const vs=[...t.querySelectorAll('details.nvver')].filter(d=>{const b=d.querySelector('summary b');return b&&nv(b.textContent)>nv(v0)});
  if(!vs.length)return;
  const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const blocos=vs.map(d=>{const b=d.querySelector('summary b').textContent,dt=(d.querySelector('summary .mut')||{}).textContent||'',ul=d.querySelector('ul');
    return '<section><h3>'+esc(b)+'<small>'+esc(dt.replace(/^\s*·\s*/,''))+'</small></h3>'+(ul?ul.outerHTML:'')+'</section>'}).join('');
  const n=vs.length;
  const dlg=document.createElement('dialog');dlg.className='nvmodal';dlg.setAttribute('aria-labelledby','nvm-t');
  dlg.innerHTML='<div class="nvm-cab"><span class="nvm-ic">'+(typeof ic==='function'?ic('sparkle',22):'★')+'</span><div><h2 id="nvm-t">O que há de novo</h2><p>'+
    (n===1?'Mudou isto desde a última vez que entrou.':'Desde a última vez que entrou saíram '+n+' versões: '+esc(vs[n-1].querySelector('summary b').textContent.replace('Versão ',''))+' a '+esc(VERSAO)+'.')+
    '</p></div></div><div class="nvm-corpo">'+blocos+'</div><div class="nvm-pe"><button class="btn primary" id="nvm-ok">Continuar</button></div>';
  document.body.appendChild(dlg);
  const fecha=()=>{try{dlg.close()}catch(_){}dlg.remove()};
  dlg.querySelector('#nvm-ok').onclick=fecha;dlg.addEventListener('cancel',e=>{e.preventDefault();fecha()});
  dlg.addEventListener('click',e=>{if(e.target===dlg)fecha()});
  try{dlg.showModal()}catch(_){dlg.setAttribute('open','')}dlg.querySelector('#nvm-ok').focus()}
/* ---------- Definições › Changelog: todas as alterações desde a criação da app ---------- */
function defChangelog(){let html='';const _od=openDrawer;try{openDrawer=(t,h)=>{html=h};novidades()}catch(e){console.warn(e)}finally{openDrawer=_od}
  const n=(html.match(/class="nvver/g)||[]).length;
  return `<div class="card defcl"><h2>${ic('list',18)} Changelog</h2><p class="hint">Todas as alterações à EduSpruce desde a primeira versão (${n} versões). Versão atual: <b>${VERSAO}</b>.</p>
  <div class="row" style="margin:6px 0 12px"><input type="search" id="cl-q" placeholder="Procurar nas alterações…" style="flex:1;min-width:200px"><button class="btn" id="cl-abre">Abrir todas</button><button class="btn" id="cl-fecha">Fechar todas</button></div>
  <div id="cl-lista">${html}</div></div>`}
function bindChangelog(){const L=$('#cl-lista');if(!L)return;
  $('#cl-abre').onclick=()=>L.querySelectorAll('details').forEach(d=>d.open=true);
  $('#cl-fecha').onclick=()=>L.querySelectorAll('details').forEach(d=>d.open=false);
  $('#cl-q').oninput=e=>{const q=e.target.value.trim().toLowerCase();L.querySelectorAll('details.nvver').forEach(d=>{let algum=false;d.querySelectorAll('li').forEach(li=>{const ok=!q||li.textContent.toLowerCase().includes(q);li.style.display=ok?'':'none';if(ok)algum=true});const v=!q||algum||d.querySelector('summary').textContent.toLowerCase().includes(q);d.style.display=v?'':'none';if(q&&v)d.open=true})}}
{const _vd=vDefinicoes;vDefinicoes=function(){const t=UI.defTab;let r;
  if(t==='changelog'){UI.defTab='auditoria';r=_vd.apply(this,arguments);UI.defTab='changelog';const tabs=$('#view .deftabs');$('#view').innerHTML='';if(tabs)$('#view').appendChild(tabs);$('#view').insertAdjacentHTML('beforeend',defChangelog());bindChangelog()}
  else r=_vd.apply(this,arguments);
  try{const tb=$('#view .deftabs');if(tb&&!tb.querySelector('[data-dtcl]')){const b=document.createElement('button');b.dataset.dtcl='1';b.innerHTML=ic('list',15)+' Changelog';tb.appendChild(b);b.onclick=()=>{UI.defTab='changelog';vDefinicoes()}}
    if(t==='changelog'&&tb)tb.querySelectorAll('button').forEach(x=>x.classList.toggle('on',!!x.dataset.dtcl))}catch(_){}return r};if(go._f)go._f.definicoes=vDefinicoes}
